INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (1, 'AEMT', 'Fluid Boluses', 'Adult', E'What is the standard adult fluid bolus amount for a patient in shock?', E'["250 mL", "500 mL", "1000 mL", "2000 mL"]', 2, E'Standard adult fluid bolus is 1000 mL (1 liter) of isotonic crystalloid solution.', E'SNHD Protocols - Fluid Therapy');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (2, 'AEMT', 'Fluid Boluses', 'Adult', E'For an adult trauma patient with suspected hemorrhagic shock, how much fluid should be administered before reassessment?', E'["250 mL", "500 mL", "1000 mL", "2000 mL"]', 2, E'Administer 1000 mL bolus and reassess. Target systolic BP of 90 mmHg (permissive hypotension).', E'SNHD Protocols - Shock');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (3, 'AEMT', 'Fluid Boluses', 'Adult', E'In traumatic brain injury with signs of herniation, what is the target systolic BP for fluid resuscitation?', E'["80-90 mmHg", "90-100 mmHg", "100-110 mmHg", "At least 110-120 mmHg"]', 3, E'In TBI, maintain SBP ≥110-120 mmHg to ensure adequate cerebral perfusion pressure.', E'SNHD Protocols - Head Trauma');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (4, 'AEMT', 'Fluid Boluses', 'Pediatric', E'What is the pediatric fluid bolus amount per kg for shock?', E'["10 mL/kg", "20 mL/kg", "30 mL/kg", "40 mL/kg"]', 1, E'Pediatric fluid bolus is 20 mL/kg of isotonic crystalloid solution.', E'SNHD Protocols - Pediatric Shock');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (5, 'AEMT', 'Fluid Boluses', 'Pediatric', E'Maximum single fluid bolus for a pediatric patient should not exceed:', E'["500 mL", "1000 mL", "1500 mL", "2000 mL"]', 1, E'Maximum single bolus is 1000 mL (1 liter), even if calculated amount is higher.', E'SNHD Protocols - Pediatric Fluid Therapy');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (6, 'AEMT', 'Fluid Boluses', 'Pediatric', E'For a 15 kg child in shock, what is the appropriate fluid bolus?', E'["150 mL", "300 mL", "500 mL", "1000 mL"]', 1, E'15 kg × 20 mL/kg = 300 mL. Pediatric bolus is calculated as 20 mL/kg.', E'SNHD Protocols - Pediatric Calculations');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (7, 'AEMT', 'Medications', 'Dosages', E'What is the pediatric dose of epinephrine for anaphylaxis?', E'["0.01 mg/kg IM (max 0.3 mg)", "0.3 mg IM", "0.5 mg IM", "1 mg IM"]', 0, E'Pediatric epinephrine is 0.01 mg/kg IM, maximum 0.3 mg (1:1000 concentration).', E'SNHD Protocols - Pediatric Allergic Reaction');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (8, 'PARAMEDIC', 'Medications', 'Dosages', E'What is the dose of naloxone for opioid overdose in adults?', E'["0.4 mg IV/IM", "2 mg IV/IM", "4 mg IV/IM", "10 mg IV/IM"]', 1, E'Initial adult dose is 2 mg IV/IM, may repeat every 2-3 minutes.', E'SNHD Protocols - Overdose/Poisoning');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (9, 'PARAMEDIC', 'Medications', 'Procedures', E'Which medication can be administered via the intranasal route?', E'["Epinephrine 1:1000", "Naloxone", "Atropine", "Adenosine"]', 1, E'Naloxone can be given intranasally (2 mg in each nostril, total 4 mg).', E'SNHD Protocols - Alternative Routes');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (10, 'PARAMEDIC', 'Medications', 'Other', E'Morphine is contraindicated in patients with:', E'["Chest pain", "Hypotension (SBP <90)", "Anxiety", "Nausea"]', 1, E'Morphine is contraindicated in hypotension (SBP <90) as it causes vasodilation and further BP drop.', E'SNHD Protocols - Pain Management');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (11, 'EMT', 'Transport Criteria', 'Transport/Admin', E'Which vital signs would allow a patient to be triaged to the waiting room?', E'["HR 120, RR 24, SBP 90", "HR 90, RR 18, SBP 130", "HR 140, RR 30, SBP 80", "GCS 13, HR 110, SBP 100"]', 1, E'Stable vitals: HR 90, RR 18, SBP 130 are within normal limits and appropriate for waiting room.', E'SNHD Protocols - Transport Decisions');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (12, 'EMT', 'Transport Criteria', 'Transport/Admin', E'A patient with minor lacerations, controlled bleeding, and vitals HR 85, BP 128/82, RR 16, SpO2 98% on room air should be transported:', E'["Code 3 (emergency)", "Code 2 (urgent)", "BLS non-emergency", "Patient can self-transport"]', 2, E'Stable patient with minor injuries - appropriate for BLS non-emergency transport.', E'SNHD Protocols - Priority Classification');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (13, 'EMT', 'Transport Criteria', 'Assessment', E'An intoxicated patient with GCS 14, stable airway, and no traumatic injuries should be transported:', E'["Left on scene with police", "Code 3 to nearest ED", "BLS to appropriate facility", "Only if they consent"]', 2, E'Intoxicated but stable patients (GCS >13, protecting airway) can be transported BLS to appropriate facility.', E'SNHD Protocols - Intoxication');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (14, 'EMT', 'Transport Criteria', 'Assessment', E'Which finding requires immediate transport of an intoxicated patient?', E'["Strong odor of alcohol", "GCS <13", "Combative behavior", "Slurred speech"]', 1, E'GCS <13 indicates significant impairment requiring emergency transport and close monitoring.', E'SNHD Protocols - Altered Mental Status');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (15, 'AEMT', 'Transport Criteria', 'Assessment', E'For a diabetic patient with altered mental status and blood glucose of 40 mg/dL, what is the first intervention?', E'["Immediate transport", "Oral glucose if awake", "IV D10 if IV established", "Glucagon IM"]', 2, E'If IV is established, give IV D10. If no IV, give oral glucose if awake/swallowing, or glucagon IM.', E'SNHD Protocols - Hypoglycemia');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (16, 'EMT', 'Trauma', 'Scoring', E'What does "TFTC" stand for in trauma designation?', E'["Too Far To Care", "Trauma Field Transport Criteria", "Transport For Trauma Care", "Trauma Facility Transport Category"]', 1, E'TFTC = Trauma Field Transport Criteria - used to determine appropriate trauma center destination.', E'SNHD Protocols - Trauma Triage');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (17, 'EMT', 'Trauma', 'Scoring', E'A patient with GCS 13, SBP 85, and RR 28 meets which trauma triage criteria?', E'["No trauma center needed", "TFTC - Transport to trauma center", "Go to nearest ED", "Wait for ALS"]', 1, E'Abnormal vital signs (GCS <14, SBP <90, RR <10 or >29) meet TFTC for trauma center transport.', E'SNHD Protocols - Trauma Triage');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (18, 'EMT', 'Trauma', 'Scoring', E'Which mechanism of injury automatically meets trauma center criteria?', E'["Fall from standing", "Fall >20 feet", "Motorcycle crash <20 mph", "Minor assault"]', 1, E'Falls >20 feet (adults) or >10 feet (children <15 years) meet trauma center criteria.', E'SNHD Protocols - Mechanism of Injury');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (19, 'PARAMEDIC', 'Trauma', 'Scoring', E'What is the Revised Trauma Score (RTS) threshold that indicates severe trauma?', E'["<5", "<7", "<11", "<15"]', 2, E'RTS <11 indicates severe trauma requiring trauma center care.', E'SNHD Protocols - Trauma Scoring');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (20, 'EMT', 'Transport', 'Transport/Admin', E'For a STEMI patient, transport should be to:', E'["Nearest ED", "PCI-capable facility", "Trauma center", "Any hospital with cardiac unit"]', 1, E'STEMI patients should go to a PCI-capable facility (catheterization lab) for emergent intervention.', E'SNHD Protocols - Cardiac Emergencies');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (21, 'EMT', 'Transport', 'Transport/Admin', E'A patient with a severe traumatic brain injury should be transported to:', E'["Nearest ED", "Trauma center with neurosurgery", "Psychiatric facility", "Urgent care"]', 1, E'Severe TBI requires a trauma center with neurosurgical capabilities.', E'SNHD Protocols - TBI Transport');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (22, 'EMT', 'Transport', 'Transport/Admin', E'For a patient in cardiac arrest, what is the transport priority?', E'["Scene time <10 min, transport to nearest", "Work on scene 20+ min", "Transport to cardiac center only", "Wait for ROSC before moving"]', 0, E'For cardiac arrest, minimize scene time (<10 min) and transport to nearest appropriate facility.', E'SNHD Protocols - Cardiac Arrest');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (23, 'EMT', 'Cardiovascular', 'OB/Neonatal', E'For a pregnant patient >20 weeks with trauma, positioning should be:', E'["Supine", "Left lateral tilt", "Trendelenburg", "Right lateral decubitus"]', 1, E'Left lateral tilt or manual uterine displacement to prevent supine hypotensive syndrome.', E'SNHD Protocols - Obstetric Trauma');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (24, 'PARAMEDIC', 'Cardiovascular', 'Other', E'For a patient with >20% TBSA burns, fluid resuscitation in first 8 hours should be:', E'["Half of total calculated", "Full amount", "Quarter of total", "None until at hospital"]', 0, E'Half of total calculated fluid (Parkland formula) is given in first 8 hours, half in next 16 hours.', E'SNHD Protocols - Burn Management');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (25, 'EMT', 'Cardiovascular', 'Environmental', E'In heat stroke, core temperature is typically:', E'[">98.6\\u00b0F", ">100\\u00b0F", ">104\\u00b0F", ">106\\u00b0F"]', 2, E'Heat stroke is defined as core temp >104°F (40°C) with altered mental status.', E'SNHD Protocols - Heat Emergencies');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (26, 'EMT', 'Respiratory', 'Special Cases', E'In a patient with suspected spinal injury, the airway maneuver of choice is:', E'["Head tilt-chin lift", "Jaw thrust", "OPA insertion", "NTA insertion"]', 1, E'Jaw thrust maneuver opens airway without extending the neck, protecting potential spinal injury.', E'SNHD Protocols - Spinal Injury');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (27, 'PARAMEDIC', 'Cardiac', 'Transport/Admin', E'In cardiac arrest with suspected opioid overdose, when should naloxone be administered?', E'["Before CPR", "After ROSC", "During CPR if IV access available", "Not indicated"]', 2, E'Naloxone may be given during CPR if opioid overdose suspected, but do NOT delay CPR/Defibrillation.', E'SNHD Protocols - Opioid Overdose');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (28, 'AEMT', 'Fluid Boluses', 'Adult', E'What type of fluid is preferred for adult bolus therapy?', E'["D5W", "Normal Saline (0.9% NaCl)", "D10", "Sterile Water"]', 1, E'Isotonic crystalloids like Normal Saline or Lactated Ringer''s are preferred for fluid resuscitation.', E'SNHD Protocols - Fluid Therapy');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (29, 'AEMT', 'Fluid Boluses', 'Pediatric', E'How many fluid boluses can be given to a pediatric patient before reassessment?', E'["1", "2", "3", "Unlimited"]', 1, E'Typically 2 boluses (40 mL/kg total) before reassessing and considering other interventions.', E'SNHD Protocols - Pediatric Shock');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (30, 'AEMT', 'Fluid Boluses', 'Adult', E'In sepsis with hypotension, what is the initial fluid bolus?', E'["250 mL", "500 mL", "1000 mL", "2000 mL"]', 2, E'30 mL/kg (typically 1000-2000 mL for adults) is the standard for septic shock.', E'SNHD Protocols - Sepsis');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (31, 'AEMT', 'Fluid Boluses', 'Adult', E'Fluid boluses are contraindicated in which condition?', E'["Hypovolemia", "Shock", "Acute pulmonary edema", "Trauma"]', 2, E'Fluid boluses are contraindicated in pulmonary edema/CHF as they worsen fluid overload.', E'SNHD Protocols - Contraindications');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (32, 'AEMT', 'Fluid Boluses', 'Pediatric', E'For a dehydrated but hemodynamically stable child, fluid administration should be:', E'["Rapid bolus", "Slow maintenance", "Nothing by mouth", "Hypertonic solution"]', 1, E'Stable dehydrated children receive slow maintenance fluids, not rapid boluses.', E'SNHD Protocols - Pediatric Dehydration');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (33, 'AEMT', 'Fluid Boluses', 'Adult', E'In hemorrhagic shock, permissive hypotension targets what SBP range?', E'["60-70 mmHg", "80-90 mmHg", "100-110 mmHg", "120+ mmHg"]', 1, E'Permissive hypotension targets SBP 80-90 mmHg to limit bleeding while maintaining perfusion.', E'SNHD Protocols - Hemorrhagic Shock');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (34, 'AEMT', 'Fluid Boluses', 'Special Cases', E'For suspected tension pneumothorax, what is the priority before fluids?', E'["Large bore IV", "Needle decompression", "Fluid bolus", "CPAP"]', 1, E'Needle decompression is lifesaving in tension pneumothorax and takes priority.', E'SNHD Protocols - Chest Trauma');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (35, 'AEMT', 'Medications', 'Dosages', E'Albuterol dosing for asthma exacerbation is:', E'["2.5 mg via nebulizer", "5 mg via nebulizer", "10 mg via nebulizer", "0.5 mg via nebulizer"]', 0, E'Standard dose is 2.5 mg in 3 mL normal saline via nebulizer, may repeat.', E'SNHD Protocols - Respiratory');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (36, 'PARAMEDIC', 'Medications', 'Procedures', E'Glucagon for hypoglycemia can be given:', E'["IV only", "IM only", "IM or SC", "PO only"]', 2, E'Glucagon can be given IM or SC (1 mg adults, 0.5 mg children <25 kg).', E'SNHD Protocols - Hypoglycemia');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (37, 'PARAMEDIC', 'Medications', 'Other', E'Nitroglycerin is contraindicated if SBP is below:', E'["100 mmHg", "90 mmHg", "110 mmHg", "120 mmHg"]', 1, E'Nitroglycerin is contraindicated if SBP <90 or >30 mmHg drop from baseline.', E'SNHD Protocols - ACS');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (38, 'PARAMEDIC', 'Medications', 'Dosages', E'Adenosine dose for SVT in adults is:', E'["3 mg rapid IV push", "6 mg rapid IV push", "12 mg rapid IV push", "0.5 mg/kg IV"]', 1, E'Start with 6 mg rapid IV push, then 12 mg if needed, then 12 mg again.', E'SNHD Protocols - Dysrhythmias');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (39, 'PARAMEDIC', 'Medications', 'Pediatric', E'Pediatric adenosine dose is:', E'["0.1 mg/kg (max 6 mg)", "0.5 mg/kg", "1 mg/kg", "6 mg fixed"]', 0, E'Pediatric adenosine: 0.1 mg/kg rapid IV (max 6 mg), then 0.2 mg/kg (max 12 mg).', E'SNHD Protocols - Pediatric Dysrhythmias');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (40, 'PARAMEDIC', 'Medications', 'Dosages', E'Amiodarone dose for cardiac arrest is:', E'["150 mg IV push", "300 mg IV push", "1 mg/kg", "450 mg IV push"]', 1, E'Cardiac arrest: 300 mg IV/IO push, may give additional 150 mg.', E'SNHD Protocols - Cardiac Arrest');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (41, 'AEMT', 'Medications', 'Procedures', E'Oral glucose can be given if the patient is:', E'["Unconscious", "Alert with intact gag reflex", "Seizing", "Vomiting"]', 1, E'Oral glucose is for alert patients with intact gag reflex who can swallow.', E'SNHD Protocols - Hypoglycemia');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (42, 'PARAMEDIC', 'Medications', 'Dosages', E'Fentanyl dosing for pain management in adults:', E'["25-50 mcg IV/IM/IN", "100-200 mcg IV", "5-10 mcg IV", "1 mg IV"]', 0, E'Fentanyl 25-50 mcg IV/IM/IN, may repeat in 10 minutes.', E'SNHD Protocols - Pain Management');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (43, 'PARAMEDIC', 'Medications', 'Other', E'Fentanyl is contraindicated with:', E'["Tachycardia", "Hypotension or respiratory depression", "Hypertension", "Anxiety"]', 1, E'Fentanyl contraindicated with hypotension (SBP <90), respiratory depression, or altered LOC.', E'SNHD Protocols - Pain Management');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (44, 'EMT', 'Transport Criteria', 'Transport/Admin', E'Which patient is appropriate for waiting room triage?', E'["Chest pain with diaphoresis", "Sore throat, afebrile, vitals stable", "Respiratory distress", "Altered mental status"]', 1, E'Stable minor complaints (sore throat, minor injuries) are appropriate for waiting room.', E'SNHD Protocols - Triage');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (45, 'EMT', 'Transport Criteria', 'Assessment', E'A patient with EtOH odor, HR 100, BP 140/90, GCS 15, no trauma should be transported:', E'["Code 3", "BLS to appropriate facility", "Left with police", "Refused transport"]', 1, E'Stable intoxicated patients can be transported BLS to appropriate facility.', E'SNHD Protocols - Intoxication');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (46, 'EMT', 'Transport Criteria', 'Assessment', E'A patient found down, unresponsive, no trauma should be:', E'["Left on scene", "Transported Code 3", "Transported BLS", "Taken home"]', 1, E'Unresponsive patients require emergency transport and evaluation.', E'SNHD Protocols - Unresponsive');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (47, 'EMT', 'Transport Criteria', 'Special Cases', E'A patient threatening suicide requires:', E'["Police only", "BLS transport", "Emergency transport with mental health evaluation", "Left with family"]', 2, E'Suicidal patients require emergency transport for mental health evaluation.', E'SNHD Protocols - Behavioral');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (48, 'EMT', 'Trauma', 'Scoring', E'The Glasgow Coma Scale assesses:', E'["Only motor response", "Eye, verbal, and motor response", "Level of pain", "Blood pressure"]', 1, E'GCS assesses eye opening, verbal response, and motor response (3-15 scale).', E'SNHD Protocols - GCS');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (49, 'EMT', 'Trauma', 'Trauma/Emergencies', E'TFTC includes which vital sign abnormalities?', E'["HR >100", "SBP <90, RR <10 or >29, GCS <14", "Temp >99\\u00b0F", "SpO2 <95%"]', 1, E'TFTC includes SBP <90, RR <10 or >29, or GCS <14.', E'SNHD Protocols - Trauma Triage');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (50, 'EMT', 'Trauma', 'Trauma/Emergencies', E'Auto vs pedestrian meets trauma center criteria if impact was at:', E'["Any speed", ">5 mph", ">20 mph", ">40 mph"]', 0, E'All auto vs pedestrian incidents meet trauma center criteria regardless of speed.', E'SNHD Protocols - Mechanism');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (51, 'EMT', 'Trauma', 'Scoring', E'A trauma patient with GCS 10, SBP 88, HR 120 meets:', E'["No trauma criteria", "TFTC - trauma center required", "BLS transport OK", "Wait for ALS"]', 1, E'GCS 10 (<14) and SBP 88 (<90) both meet TFTC criteria.', E'SNHD Protocols - Trauma Scoring');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (52, 'EMT', 'Trauma', 'Special Cases', E'Ejection from vehicle meets trauma center criteria:', E'["Only if >20 mph", "Only if rollover", "Yes - automatic criteria", "Only if unrestrained"]', 2, E'Ejection from vehicle is automatic trauma center criteria regardless of other factors.', E'SNHD Protocols - Mechanism');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (53, 'EMT', 'Trauma', 'Pediatric', E'Pediatric trauma activation age threshold is typically under:', E'["5 years", "10 years", "15 years", "18 years"]', 2, E'Many systems use <15 years for pediatric trauma criteria (falls >10 feet).', E'SNHD Protocols - Pediatric Trauma');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (54, 'EMT', 'Cardiac', 'Other', E'Adult CPR compression rate is:', E'["60-80 per minute", "100-120 per minute", "140-160 per minute", "As fast as possible"]', 1, E'AHA recommends 100-120 compressions per minute for adults.', E'SNHD Protocols - CPR');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (55, 'EMT', 'Cardiac', 'Other', E'CPR compression depth for adults is:', E'["At least 1 inch", "At least 2 inches (5 cm)", "3-4 inches", "1.5 inches"]', 1, E'Compress at least 2 inches (5 cm) but not more than 2.4 inches.', E'SNHD Protocols - CPR');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (56, 'PARAMEDIC', 'Cardiac', 'Cardiac/Respiratory', E'Unstable tachycardia with a pulse is treated with:', E'["CPR", "Synchronized cardioversion", "Defibrillation", "Observation"]', 1, E'Unstable tachycardia (hypotension, altered LOC, chest pain) requires synchronized cardioversion.', E'SNHD Protocols - Tachycardia');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (57, 'PARAMEDIC', 'Cardiac', 'Cardiac/Respiratory', E'STEMI is defined by ST elevation of:', E'[">0.5 mm", ">1 mm in limb leads, >2 mm in precordial leads", ">3 mm anywhere", "Any ST elevation"]', 1, E'STEMI: >1 mm ST elevation in limb leads or >2 mm in precordial leads (V1-V6).', E'SNHD Protocols - STEMI');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (58, 'EMT', 'Cardiac', 'Cardiac/Respiratory', E'Aspirin for chest pain should be given:', E'["Only if 12-lead shows MI", "To all patients with suspected ACS", "Only if hypertensive", "Never by EMTs"]', 1, E'Aspirin 324 mg chewable is given to all suspected ACS patients without allergy.', E'SNHD Protocols - Chest Pain');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (59, 'PARAMEDIC', 'Cardiac', 'Cardiac/Respiratory', E'Nitroglycerin should NOT be given if:', E'["HR >100", "SBP <90 or used PDE5 inhibitor", "Patient is anxious", "Pain is severe"]', 1, E'Nitroglycerin contraindicated if SBP <90, HR <50 or >100, or PDE5 inhibitor use.', E'SNHD Protocols - ACS');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (60, 'EMT', 'Respiratory', 'Assessment', E'Signs of respiratory distress include:', E'["Normal breathing", "Accessory muscle use, tripod positioning", "Bradypnea", "Sleepiness"]', 1, E'Accessory muscle use, tripod position, retractions indicate respiratory distress.', E'SNHD Protocols - Respiratory');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (61, 'EMT', 'Respiratory', 'Cardiac/Respiratory', E'Status asthmaticus is defined as:', E'["Mild wheezing", "Asthma not responding to initial treatment", "No wheezing", "Normal SpO2"]', 1, E'Status asthmaticus is severe asthma not responding to initial bronchodilator therapy.', E'SNHD Protocols - Asthma');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (62, 'EMT', 'Respiratory', 'Cardiac/Respiratory', E'COPD patients often have baseline:', E'["High SpO2", "Low SpO2 (88-92% acceptable)", "Normal CO2", "Alkalosis"]', 1, E'COPD patients may have baseline SpO2 88-92% due to chronic CO2 retention.', E'SNHD Protocols - COPD');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (63, 'PARAMEDIC', 'Respiratory', 'Assessment', E'Signs of impending respiratory failure include:', E'["Improved SpO2 with O2", "Altered mental status, fatigue, bradypnea", "Increased wheezing", "Tachycardia only"]', 1, E'Altered mental status, fatigue, bradypnea indicate respiratory failure requiring airway support.', E'SNHD Protocols - Respiratory Failure');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (64, 'EMT', 'Pediatric', 'Assessment', E'Pediatric vital signs differ from adults. Normal pediatric HR is:', E'["60-100 for all ages", "Faster than adults, varies by age", "Slower than adults", "Always >150"]', 1, E'Pediatric heart rates are faster and vary by age (infants 100-160, toddlers 90-150, etc.).', E'SNHD Protocols - Pediatric Vitals');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (65, 'EMT', 'Pediatric', 'Cardiac/Respiratory', E'Pediatric airway positioning for infants requires:', E'["Head hyperextension", "Neutral position (towel under shoulders)", "Chin to chest", "Lateral position"]', 1, E'Infants need neutral position with towel under shoulders due to large occiput.', E'SNHD Protocols - Pediatric Airway');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (66, 'EMT', 'Pediatric', 'Assessment', E'Febrile seizure is most common in ages:', E'["0-3 months", "6 months - 5 years", "5-10 years", "All ages equally"]', 1, E'Febrile seizures most common in children 6 months to 5 years old.', E'SNHD Protocols - Pediatric Seizures');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (67, 'AEMT', 'Pediatric', 'Medications', E'Pediatric epinephrine for anaphylaxis is dosed at:', E'["0.01 mg/kg IM (max 0.3 mg)", "0.3 mg IM fixed dose", "0.5 mg IM", "1 mg IM"]', 0, E'Pediatric epinephrine: 0.01 mg/kg IM (max 0.3 mg) using 1:1000 concentration.', E'SNHD Protocols - Pediatric Anaphylaxis');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (68, 'EMT', 'Pediatric', 'Trauma/Emergencies', E'Pediatric trauma patients are at higher risk for:', E'["Hypertension", "Hypovolemic shock (large body surface area)", "Bradycardia", "Hyperthermia"]', 1, E'Children have larger body surface area to volume ratio and decompensate quickly.', E'SNHD Protocols - Pediatric Trauma');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (69, 'EMT', 'Obstetric', 'OB/Neonatal', E'Signs of imminent delivery include:', E'["Contractions 10 minutes apart", "Crowning, urge to push, contractions <2 min apart", "No contractions", "Mild cramping"]', 1, E'Crowning, urge to push, and frequent contractions indicate imminent delivery.', E'SNHD Protocols - Childbirth');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (70, 'EMT', 'Obstetric', 'OB/Neonatal', E'Shoulder dystocia is managed by:', E'["Immediate transport", "McRoberts maneuver (knees to chest)", "Fundal pressure", "Pulling harder on baby"]', 1, E'McRoberts maneuver (hyperflex maternal thighs) is first-line for shoulder dystocia.', E'SNHD Protocols - Shoulder Dystocia');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (71, 'EMT', 'Obstetric', 'OB/Neonatal', E'Postpartum hemorrhage is defined as blood loss >:', E'["100 mL", "500 mL (vaginal) or 1000 mL (C-section)", "250 mL", "2000 mL"]', 1, E'PPH: >500 mL after vaginal delivery or >1000 mL after C-section.', E'SNHD Protocols - Postpartum Hemorrhage');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (72, 'EMT', 'Obstetric', 'Trauma/Emergencies', E'Eclampsia is characterized by:', E'["High blood pressure only", "Seizures in pregnancy/postpartum", "Low blood pressure", "Normal delivery"]', 1, E'Eclampsia is new-onset seizures in pregnancy or postpartum, usually with hypertension.', E'SNHD Protocols - Eclampsia');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (73, 'EMT', 'Environmental', 'Environmental', E'Heat exhaustion vs heat stroke - key difference is:', E'["Temperature only", "Altered mental status in heat stroke", "Sweating", "Heart rate"]', 1, E'Heat stroke has altered mental status + temp >104°F; heat exhaustion has normal mentation.', E'SNHD Protocols - Heat Emergencies');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (74, 'EMT', 'Environmental', 'Environmental', E'Severe hypothermia is core temp below:', E'["95\\u00b0F (35\\u00b0C)", "90\\u00b0F (32\\u00b0C)", "86\\u00b0F (30\\u00b0C)", "98.6\\u00b0F"]', 1, E'Severe hypothermia is core temp <90°F (32°C) - may present as pulseless.', E'SNHD Protocols - Hypothermia');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (75, 'EMT', 'Environmental', 'Trauma/Emergencies', E'Priority in drowning is:', E'["Immediate CPR regardless", "Airway and breathing assessment", "Spinal immobilization", "Transport only"]', 1, E'Assess ABCs first - not all drowning victims need immediate CPR if breathing.', E'SNHD Protocols - Drowning');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (76, 'EMT', 'Environmental', 'Environmental', E'High altitude illness symptoms include:', E'["Only headache", "HAPE and HACE", "Increased appetite", "Hypothermia only"]', 1, E'High altitude illness includes HAPE (pulmonary edema) and HACE (cerebral edema).', E'SNHD Protocols - Altitude');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (77, 'EMT', 'Behavioral', 'Assessment', E'First priority in behavioral emergency is:', E'["Immediate sedation", "Scene safety", "Psychiatric diagnosis", "Physical restraint"]', 1, E'Scene safety for crew and patient is always the first priority.', E'SNHD Protocols - Behavioral');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (78, 'EMT', 'Behavioral', 'Trauma/Emergencies', E'Restraint should be:', E'["Prone position", "Minimum necessary, supine or lateral", "Tied tightly", "Ignored"]', 1, E'Use minimum necessary restraint, avoid prone position, monitor closely.', E'SNHD Protocols - Restraint');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (79, 'EMT', 'Behavioral', 'Trauma/Emergencies', E'Patient with suicide attempt requires:', E'["Police only", "Emergency transport to ED for evaluation", "Family to watch", "Promise not to do it again"]', 1, E'All suicide attempts/ideation require emergency transport for professional evaluation.', E'SNHD Protocols - Suicide');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (80, 'EMT', 'Pediatric', 'Fluid Boluses', E'For a 20 kg child in hypovolemic shock, what is the correct fluid bolus?', E'["200 mL", "400 mL", "600 mL", "1000 mL"]', 1, E'20 kg × 20 mL/kg = 400 mL. Pediatric bolus is always 20 mL/kg.', E'SNHD Protocols - Pediatric Fluids');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (81, 'EMT', 'Pediatric', 'Fluid Boluses', E'Maximum number of fluid boluses recommended before reassessment in pediatrics:', E'["1 bolus", "2 boluses (40 mL/kg total)", "3 boluses", "Unlimited until BP normalizes"]', 1, E'Maximum 2 boluses (40 mL/kg total) before reassessment. Consider other interventions if still unstable.', E'SNHD Protocols - Pediatric Shock');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (82, 'EMT', 'Pediatric', 'Fluid Boluses', E'A 35 kg pediatric patient should receive a maximum single bolus of:', E'["700 mL (35 kg \\u00d7 20)", "1000 mL", "500 mL", "1500 mL"]', 1, E'Calculated amount is 700 mL, but maximum single bolus is capped at 1000 mL.', E'SNHD Protocols - Pediatric Fluid Limits');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (83, 'AEMT', 'Pediatric', 'Fluid Boluses', E'Fluid bolus is contraindicated in pediatric patients with:', E'["Fever", "Respiratory distress with rales/crackles", "Normal vitals", "Minor trauma"]', 1, E'Fluid bolus contraindicated in suspected CHF, pulmonary edema, or respiratory distress with fluid overload signs.', E'SNHD Protocols - Pediatric Contraindications');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (84, 'AEMT', 'Pediatric', 'Fluid Boluses', E'For pediatric DKA (Diabetic Ketoacidosis), fluid resuscitation should be:', E'["Rapid bolus to correct shock quickly", "Cautious - risk of cerebral edema", "Not given until glucose normalized", "Hypertonic saline"]', 1, E'DKA requires cautious fluid resuscitation due to risk of cerebral edema. Follow specific DKA protocols.', E'SNHD Protocols - Pediatric DKA');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (85, 'EMT', 'Pediatric', 'Fluid Boluses', E'A neonate (under 28 days) in shock receives fluid bolus of:', E'["20 mL/kg", "10 mL/kg", "30 mL/kg", "40 mL/kg"]', 1, E'Neonates receive 10 mL/kg boluses due to risk of fluid overload and heart strain.', E'SNHD Protocols - Neonatal Resuscitation');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (86, 'AEMT', 'Pediatric', 'Fluid Boluses', E'Signs of fluid overload in pediatric patients include:', E'["Tachycardia only", "Hepatomegaly, JVD, rales, decreased responsiveness", "Fever", "Increased urine output"]', 1, E'Hepatomegaly (enlarged liver), JVD, pulmonary rales, and altered mental status indicate fluid overload.', E'SNHD Protocols - Pediatric Complications');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (87, 'EMT', 'Pediatric', 'Fluid Boluses', E'For a 6-year-old (22 kg) with suspected sepsis and normal perfusion, initial fluid is:', E'["No fluids", "20 mL/kg bolus over 20 minutes", "Maintenance only", "D5W bolus"]', 1, E'Pediatric sepsis: 20 mL/kg isotonic crystalloid bolus, reassess perfusion after each bolus.', E'SNHD Protocols - Pediatric Sepsis');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (88, 'AEMT', 'Pediatric', 'Fluid Boluses', E'In pediatric trauma with suspected hemorrhage but no signs of shock:', E'["No fluids", "Aggressive fluid resuscitation", "Limited fluids, permissive hypotension", "Blood transfusion"]', 2, E'In pediatric trauma without shock, use limited fluids with permissive hypotension to avoid dilutional coagulopathy.', E'SNHD Protocols - Pediatric Trauma');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (89, 'PARAMEDIC', 'Pediatric', 'Fluid Boluses', E'Burn fluid resuscitation for a 15 kg child with 20% TBSA burns (Parkland formula):', E'["150 mL/hr", "300 mL/hr for first 8 hours", "600 mL total", "No fluids in field"]', 1, E'Parkland: 4 mL × kg × %TBSA = 1200 mL. Half in first 8 hours = 600 mL total, 75 mL/hr. First 8 hours from time of burn.', E'SNHD Protocols - Pediatric Burns');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (90, 'AEMT', 'Pediatric', 'Medications', E'Pediatric albuterol dosing via nebulizer is:', E'["0.15 mg/kg (min 2.5 mg, max 5 mg)", "2.5 mg fixed dose", "5 mg fixed dose", "0.5 mg/kg"]', 0, E'Pediatric albuterol: 0.15 mg/kg, minimum 2.5 mg, maximum 5 mg per treatment.', E'SNHD Protocols - Pediatric Asthma');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (91, 'EMT', 'Pediatric', 'Medications', E'A 3-year-old (14 kg) with anaphylaxis receives epinephrine at:', E'["0.14 mg IM (0.01 mg/kg)", "0.3 mg IM", "0.5 mg IM", "1 mg IM"]', 0, E'Pediatric epinephrine: 0.01 mg/kg IM using 1:1000 concentration. 14 kg × 0.01 = 0.14 mg.', E'SNHD Protocols - Pediatric Anaphylaxis');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (92, 'AEMT', 'Pediatric', 'Medications', E'Maximum pediatric dose of epinephrine for anaphylaxis is:', E'["0.15 mg", "0.3 mg", "0.5 mg", "1 mg"]', 1, E'Maximum pediatric epinephrine dose is 0.3 mg IM (1:1000), even if calculated dose is higher.', E'SNHD Protocols - Pediatric Med Limits');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (93, 'PARAMEDIC', 'Pediatric', 'Medications', E'Pediatric midazolam (Versed) for seizures is dosed at:', E'["0.1 mg/kg IM/IN (max 5 mg)", "0.5 mg/kg IM", "5 mg fixed dose", "0.05 mg/kg IV only"]', 0, E'Pediatric midazolam: 0.1 mg/kg IM/IN, maximum 5 mg. Can repeat once in 5-10 minutes.', E'SNHD Protocols - Pediatric Seizures');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (94, 'PARAMEDIC', 'Pediatric', 'Medications', E'Pediatric naloxone for opioid overdose can be given:', E'["Only IV", "IV/IM/IN", "Only IN", "Contraindicated"]', 1, E'Pediatric naloxone: 2 mg IN (1 mg each nostril) or 0.1 mg/kg IV/IM (max 2 mg).', E'SNHD Protocols - Pediatric Overdose');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (95, 'AEMT', 'Pediatric', 'Medications', E'Pediatric oral glucose gel can be given if:', E'["Patient is unconscious", "Patient is alert with gag reflex", "Patient is seizing", "Patient is vomiting"]', 1, E'Oral glucose only for alert pediatric patients with intact gag reflex who can swallow.', E'SNHD Protocols - Pediatric Hypoglycemia');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (96, 'PARAMEDIC', 'Pediatric', 'Medications', E'Pediatric fentanyl for pain management is contraindicated with:', E'["Fever", "Respiratory depression or altered mental status", "Crying", "Normal vitals"]', 1, E'Fentanyl contraindicated in pediatrics with respiratory depression, altered LOC, or hemodynamic instability.', E'SNHD Protocols - Pediatric Pain');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (97, 'PARAMEDIC', 'Pediatric', 'Medications', E'Pediatric diphenhydramine (Benadryl) dose for allergic reaction:', E'["0.5 mg/kg IV/IM (max 25 mg)", "25 mg fixed dose", "50 mg fixed dose", "1 mg/kg (max 100 mg)"]', 0, E'Pediatric diphenhydramine: 1 mg/kg PO or 0.5 mg/kg IV/IM, maximum 25 mg.', E'SNHD Protocols - Pediatric Allergies');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (98, 'AEMT', 'Pediatric', 'Medications', E'A 5-year-old (18 kg) with severe pain can receive fentanyl at:', E'["0.5 mcg/kg IN (max 50 mcg)", "1 mcg/kg IN (max 100 mcg)", "25 mcg fixed dose", "50 mcg fixed dose"]', 1, E'Pediatric fentanyl: 1 mcg/kg IN, maximum 100 mcg (50 mcg per nostril).', E'SNHD Protocols - Pediatric Pain Management');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (99, 'PARAMEDIC', 'Pediatric', 'Medications', E'Pediatric adenosine for SVT requires:', E'["Defibrillation first", "Rapid IV push followed by saline flush", "Slow IV drip", "IM injection"]', 1, E'Adenosine must be given as rapid IV push followed immediately by 5-10 mL saline flush.', E'SNHD Protocols - Pediatric Dysrhythmias');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (100, 'PARAMEDIC', 'Pediatric', 'Medications', E'Pediatric amiodarone dosing for ventricular fibrillation:', E'["1 mg/kg IV/IO (max 100 mg)", "5 mg/kg IV/IO (max 300 mg)", "150 mg fixed dose", "300 mg fixed dose"]', 1, E'Pediatric amiodarone: 5 mg/kg IV/IO, maximum 300 mg for cardiac arrest.', E'SNHD Protocols - Pediatric Cardiac Arrest');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (101, 'AEMT', 'Pediatric', 'Medications', E'Pediatric ondansetron (Zofran) for vomiting is contraindicated in:', E'["Fever", "Known prolonged QT syndrome", "Dehydration", "All pediatric patients"]', 1, E'Ondansetron is contraindicated in prolonged QT syndrome due to risk of torsades.', E'SNHD Protocols - Pediatric Contraindications');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (102, 'PARAMEDIC', 'Pediatric', 'Medications', E'Pediatric dextrose (D10) for hypoglycemia is given at:', E'["0.5 g/kg (5 mL/kg) slow IV", "1 g/kg (10 mL/kg) rapid IV", "2 g/kg IV push", "D25 preferred"]', 0, E'Pediatric D10: 5 mL/kg (0.5 g/kg) slow IV. D10 is preferred over D25/D50 in pediatrics.', E'SNHD Protocols - Pediatric Hypoglycemia');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (103, 'EMT', 'Pediatric', 'Medications', E'Pediatric acetaminophen (Tylenol) rectal dose for fever:', E'["5 mg/kg", "10 mg/kg", "15 mg/kg", "20 mg/kg"]', 2, E'Pediatric acetaminophen: 15 mg/kg PO or PR, maximum 75 mg/kg/day (not to exceed adult max).', E'SNHD Protocols - Pediatric Fever');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (104, 'PARAMEDIC', 'Pediatric', 'Medications', E'Pediatric succinylcholine for RSI is dosed at:', E'["0.5 mg/kg", "1 mg/kg", "2 mg/kg", "3 mg/kg"]', 2, E'Pediatric succinylcholine: 2 mg/kg IV (higher dose than adults due to larger volume of distribution).', E'SNHD Protocols - Pediatric RSI');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (105, 'PARAMEDIC', 'Pediatric', 'Medications', E'Pediatric rocuronium for RSI is dosed at:', E'["0.3 mg/kg", "0.6 mg/kg", "1.2 mg/kg", "1.6 mg/kg"]', 2, E'Pediatric rocuronium for RSI: 1.2 mg/kg IV (higher dose than adults).', E'SNHD Protocols - Pediatric Airway');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (106, 'EMT', 'Pediatric', 'Special Cases', E'In pediatric bradycardia with poor perfusion, first intervention is:', E'["Atropine", "Epinephrine", "Oxygenation and ventilation support", "Defibrillation"]', 2, E'Pediatric bradycardia is usually due to hypoxia - oxygenate and ventilate first.', E'SNHD Protocols - Pediatric Bradycardia');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (107, 'AEMT', 'Pediatric', 'Special Cases', E'Pediatric dose calculation using Broselow tape is based on:', E'["Age", "Weight only", "Length/height", "Head circumference"]', 2, E'Broselow tape uses patient length to estimate weight and provide medication dosing.', E'SNHD Protocols - Pediatric Equipment');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (108, 'EMT', 'Pediatric', 'Special Cases', E'During pediatric respiratory arrest with a pulse, ventilate at:', E'["30 breaths/minute", "20-30 breaths/minute", "12-20 breaths/minute", "As fast as possible"]', 1, E'Pediatric with pulse: ventilate 20-30 breaths/minute (every 2-3 seconds).', E'SNHD Protocols - Pediatric Ventilation');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (109, 'PARAMEDIC', 'Pediatric', 'Special Cases', E'Pediatric septic shock may present with:', E'["Hypertension", "Normal or low BP with signs of poor perfusion (compensated shock)", "Bradycardia", "Increased urine output"]', 1, E'Pediatric patients compensate well - may have normal BP but poor perfusion (tachycardia, delayed cap refill, altered mentation).', E'SNHD Protocols - Pediatric Shock Recognition');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (110, 'EMT', 'Pediatric', 'Special Cases', E'For infants, proper BVM technique requires:', E'["One hand for seal, one for squeeze", "Two hands for seal, one for squeeze", "One person only", "High pressure ventilation"]', 1, E'Infant BVM: Two hands for mask seal (E-C technique), one person squeezes bag. Prevents air leaks.', E'SNHD Protocols - Pediatric BVM');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (111, 'AEMT', 'Pediatric', 'Special Cases', E'Pediatric IO (intraosseous) access is preferred in children under:', E'["2 years", "6 years", "12 years", "Any age if no IV access"]', 1, E'IO is preferred in children under 6 years when IV access difficult or delayed. Can be used in any age.', E'SNHD Protocols - Pediatric Access');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (112, 'EMT', 'Pediatric', 'Special Cases', E'During pediatric fever with altered mental status, suspect:', E'["Simple viral illness", "Febrile seizure, meningitis, or sepsis", "Heat exhaustion", "Hypoglycemia only"]', 1, E'Fever + altered mental status in pediatrics is serious - consider febrile seizure, meningitis, or sepsis.', E'SNHD Protocols - Pediatric Fever Workup');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (113, 'PARAMEDIC', 'Pediatric', 'Special Cases', E'Pediatric post-intubation sedation and analgesia should include:', E'["No medications needed", "Analgesia (pain control) AND sedation", "Sedation only", "Paralytic only"]', 1, E'Intubated pediatric patients require both analgesia (fentanyl) AND sedation (midazolam/ketamine).', E'SNHD Protocols - Pediatric Post-Intubation');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (114, 'EMT', 'Pediatric', 'Special Cases', E'For suspected non-accidental trauma in pediatrics, you should:', E'["Confront the parents immediately", "Document findings objectively and report suspicions", "Ignore it as not your concern", "Transport without documentation"]', 1, E'Document objective findings, mechanism inconsistencies, and report suspicions to receiving facility.', E'SNHD Protocols - Pediatric Abuse');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (115, 'PARAMEDIC', 'Pediatric', 'Special Cases', E'Pediatric traumatic arrest with asystole has:', E'["Good prognosis with aggressive resuscitation", "Poor prognosis - consider terminating if no reversible cause", "Always due to hypothermia", "Better outcomes than adults"]', 1, E'Pediatric traumatic arrest in asystole has very poor prognosis. Consider termination if no reversible cause found.', E'SNHD Protocols - Pediatric Traumatic Arrest');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (116, 'EMT', 'Pediatric', 'Fluid Boluses', E'A 4-year-old weighing 16 kg needs a fluid bolus. Calculate: 16 kg × 20 mL/kg = ?', E'["240 mL", "320 mL", "400 mL", "480 mL"]', 1, E'16 kg × 20 mL/kg = 320 mL. This is under the 1000 mL cap, so give full 320 mL.', E'SNHD Protocols - Pediatric Fluid Calculation');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (117, 'EMT', 'Pediatric', 'Fluid Boluses', E'An 8-year-old weighing 25 kg needs a fluid bolus. Calculate amount and apply cap: 25 kg × 20 mL/kg = ?', E'["400 mL", "500 mL", "750 mL", "1000 mL (capped)"]', 1, E'25 kg × 20 mL/kg = 500 mL. Under 1000 mL cap, so give 500 mL.', E'SNHD Protocols - Pediatric Fluid Calculation');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (118, 'EMT', 'Pediatric', 'Fluid Boluses', E'A 12-year-old weighing 55 kg needs a fluid bolus. Calculate: 55 kg × 20 mL/kg = ? Apply cap.', E'["800 mL", "1000 mL (capped)", "1100 mL", "1200 mL"]', 1, E'55 kg × 20 mL/kg = 1100 mL, BUT maximum single bolus is 1000 mL. Give 1000 mL.', E'SNHD Protocols - Pediatric Fluid Cap');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (119, 'EMT', 'Pediatric', 'Fluid Boluses', E'A 2-year-old weighing 12 kg is in hypovolemic shock. First bolus is 12 kg × 20 mL/kg = ?', E'["200 mL", "240 mL", "300 mL", "400 mL"]', 1, E'12 kg × 20 mL/kg = 240 mL first bolus. Reassess after administration.', E'SNHD Protocols - Pediatric Shock');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (120, 'AEMT', 'Pediatric', 'Fluid Boluses', E'After first bolus, the 12 kg child remains hypotensive. Second bolus calculation: 12 kg × 20 mL/kg = ? Total given?', E'["120 mL, total 360 mL", "240 mL, total 480 mL (40 mL/kg)", "500 mL, total 740 mL", "1000 mL total"]', 1, E'Second bolus is another 240 mL. Total is 480 mL or 40 mL/kg. Maximum recommended before reassessment.', E'SNHD Protocols - Pediatric Bolus Limits');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (121, 'EMT', 'Pediatric', 'Fluid Boluses', E'A 5-year-old weighs 18 kg. Calculate fluid bolus: 18 kg × 20 mL/kg = ?', E'["300 mL", "360 mL", "400 mL", "500 mL"]', 1, E'18 kg × 20 mL/kg = 360 mL bolus.', E'SNHD Protocols - Pediatric Calculation');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (122, 'EMT', 'Pediatric', 'Fluid Boluses', E'A 7-month-old infant weighs 8 kg. Calculate bolus: 8 kg × 20 mL/kg = ?', E'["120 mL", "160 mL", "200 mL", "240 mL"]', 1, E'8 kg × 20 mL/kg = 160 mL bolus for this infant.', E'SNHD Protocols - Pediatric Infant Fluids');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (123, 'EMT', 'Pediatric', 'Fluid Boluses', E'A 10-year-old weighs 32 kg. Calculate: 32 kg × 20 mL/kg = ?', E'["540 mL", "640 mL", "740 mL", "840 mL"]', 1, E'32 kg × 20 mL/kg = 640 mL bolus.', E'SNHD Protocols - Pediatric Calculation');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (124, 'AEMT', 'Pediatric', 'Fluid Boluses', E'A 14 kg child has received 2 boluses and remains unstable. You have given 14 kg × 20 mL/kg × 2 = ?', E'["420 mL", "560 mL", "640 mL", "760 mL"]', 1, E'14 kg × 20 mL/kg = 280 mL per bolus. Two boluses = 560 mL total (40 mL/kg). Consider other interventions.', E'SNHD Protocols - Pediatric Maximum Boluses');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (125, 'PARAMEDIC', 'Pediatric', 'Fluid Boluses', E'A 50 kg adolescent in DKA with pH 7.1 and altered mental status. Fluid calculation: 50 kg × 20 mL/kg = ? Special consideration?', E'["1000 mL - give rapidly", "1000 mL - give cautiously due to cerebral edema risk", "2000 mL - DKA needs more", "No fluids until glucose normalized"]', 1, E'DKA patients get 20 mL/kg (1000 mL) BUT must be given cautiously over 1-2 hours due to cerebral edema risk.', E'SNHD Protocols - DKA Fluids');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (126, 'EMT', 'Pediatric', 'Fluid Boluses', E'A 3-day-old neonate weighs 3.5 kg and is in shock. Neonatal bolus: 3.5 kg × 10 mL/kg = ?', E'["25 mL", "35 mL", "50 mL", "70 mL"]', 1, E'Neonates (<28 days) receive 10 mL/kg boluses. 3.5 kg × 10 = 35 mL.', E'SNHD Protocols - Neonatal Bolus');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (127, 'AEMT', 'Pediatric', 'Fluid Boluses', E'A 9 kg infant in shock. First bolus: 9 kg × 20 mL/kg = ? Second bolus if needed?', E'["180 mL, then 180 mL more", "200 mL, then 200 mL more", "150 mL, then reassess", "No bolus - infants get IV only"]', 0, E'9 kg × 20 = 180 mL first bolus. If still unstable, second 180 mL bolus for total 360 mL (40 mL/kg).', E'SNHD Protocols - Pediatric Infants');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (128, 'PARAMEDIC', 'Pediatric', 'Fluid Boluses', E'A 22 kg child has 30% TBSA burns. Using Parkland formula (4 mL × kg × %TBSA): 4 × 22 × 30 = ? First 8 hours?', E'["1320 mL total, 660 mL in first 8 hours", "2640 mL total, 1320 mL in first 8 hours", "3000 mL total", "500 mL in first 8 hours"]', 1, E'Parkland: 4 × 22 × 30 = 2640 mL total. Half in first 8 hours = 1320 mL.', E'SNHD Protocols - Burn Calculation');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (129, 'EMT', 'Pediatric', 'Fluid Boluses', E'A 6-year-old weighs 21 kg and has severe vomiting with signs of shock. Bolus calculation: 21 kg × 20 mL/kg = ?', E'["320 mL", "420 mL", "520 mL", "620 mL"]', 1, E'21 kg × 20 mL/kg = 420 mL first bolus for hypovolemic shock.', E'SNHD Protocols - Dehydration');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (130, 'AEMT', 'Pediatric', 'Fluid Boluses', E'A 28 kg child needs fluids but has rales and JVD. What do you do?', E'["Give full 560 mL bolus", "Give half bolus (280 mL)", "No bolus - suspected CHF/fluid overload", "Give 1000 mL regardless"]', 2, E'Rales and JVD indicate fluid overload/CHF. Fluid bolus is CONTRAINDICATED.', E'SNHD Protocols - Pediatric Contraindications');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (131, 'EMT', 'Pediatric', 'Fluid Boluses', E'A 15-month-old weighs 10 kg and is lethargic with delayed cap refill. Bolus: 10 kg × 20 mL/kg = ?', E'["150 mL", "200 mL", "250 mL", "300 mL"]', 1, E'10 kg × 20 mL/kg = 200 mL first bolus for shock.', E'SNHD Protocols - Toddler Fluids');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (132, 'AEMT', 'Pediatric', 'Medications', E'A 9-year-old weighs 27 kg and has anaphylaxis. Epinephrine: 27 kg × 0.01 mg/kg = ? mg IM (max 0.3 mg)', E'["0.2 mg", "0.27 mg", "0.3 mg (capped)", "0.5 mg"]', 1, E'27 kg × 0.01 = 0.27 mg IM. Under 0.3 mg max, so give 0.27 mg of 1:1000.', E'SNHD Protocols - Epinephrine Calculation');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (133, 'AEMT', 'Pediatric', 'Medications', E'A 5-year-old weighs 19 kg with anaphylaxis. Epinephrine: 19 kg × 0.01 mg/kg = ? Check against max.', E'["0.15 mg", "0.19 mg", "0.25 mg", "0.3 mg (capped)"]', 1, E'19 kg × 0.01 = 0.19 mg IM. Under 0.3 mg max, so give full calculated dose.', E'SNHD Protocols - Pediatric Anaphylaxis');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (134, 'AEMT', 'Pediatric', 'Medications', E'A 35 kg child has anaphylaxis. Epinephrine: 35 kg × 0.01 = 0.35 mg. Apply max. Dose?', E'["0.3 mg (capped)", "0.35 mg", "0.4 mg", "0.5 mg"]', 0, E'Calculated 0.35 mg, but MAXIMUM pediatric epinephrine is 0.3 mg IM. Give 0.3 mg.', E'SNHD Protocols - Pediatric Med Max');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (135, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 12 kg child has status epilepticus. Midazolam: 12 kg × 0.1 mg/kg = ? mg IM/IN (max 5 mg)', E'["0.8 mg", "1.0 mg", "1.2 mg", "5 mg"]', 2, E'12 kg × 0.1 = 1.2 mg IM/IN. Under 5 mg max, so give 1.2 mg.', E'SNHD Protocols - Midazolam Calc');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (136, 'PARAMEDIC', 'Pediatric', 'Medications', E'An 8-year-old weighs 23 kg with asthma. Albuterol: 23 kg × 0.15 mg/kg = ? mg (min 2.5 mg, max 5 mg)', E'["2.5 mg (minimum)", "3.45 mg", "5 mg (maximum)", "7 mg"]', 1, E'23 kg × 0.15 = 3.45 mg. Between 2.5-5 mg range, so give 3.45 mg (or round to 3.5 mg).', E'SNHD Protocols - Albuterol Calc');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (137, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 4-year-old weighs 16 kg with severe asthma. Albuterol: 16 kg × 0.15 = 2.4 mg. Check min/max.', E'["2.4 mg", "2.5 mg (minimum)", "3 mg", "5 mg"]', 1, E'Calculated 2.4 mg, but MINIMUM is 2.5 mg. Give at least 2.5 mg.', E'SNHD Protocols - Albuterol Min');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (138, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 40 kg child with severe pain. Fentanyl: 40 kg × 1 mcg/kg = ? mcg IN (max 100 mcg)', E'["30 mcg", "40 mcg", "50 mcg", "100 mcg"]', 1, E'40 kg × 1 mcg/kg = 40 mcg IN. Under 100 mcg max. Give 40 mcg (20 mcg per nostril).', E'SNHD Protocols - Fentanyl Calc');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (139, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 55 kg adolescent needs fentanyl. 55 kg × 1 mcg/kg = 55 mcg. Max is 100 mcg. Dose?', E'["50 mcg", "55 mcg", "100 mcg", "150 mcg"]', 2, E'55 mcg calculated, but can give up to 100 mcg max. Consider giving 100 mcg for severe pain.', E'SNHD Protocols - Fentanyl Max');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (140, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 7 kg infant is hypoglycemic. D10: 7 kg × 5 mL/kg = ? mL slow IV', E'["25 mL", "30 mL", "35 mL", "50 mL"]', 2, E'7 kg × 5 mL/kg = 35 mL D10 slow IV push for hypoglycemia.', E'SNHD Protocols - D10 Calculation');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (141, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 30 kg child needs RSI. Rocuronium: 30 kg × 1.2 mg/kg = ? mg IV', E'["24 mg", "30 mg", "36 mg", "40 mg"]', 2, E'30 kg × 1.2 mg/kg = 36 mg IV rocuronium for paralysis.', E'SNHD Protocols - Rocuronium Calc');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (142, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 20 kg child needs succinylcholine for RSI. 20 kg × 2 mg/kg = ? mg IV', E'["30 mg", "35 mg", "40 mg", "50 mg"]', 2, E'20 kg × 2 mg/kg = 40 mg IV succinylcholine.', E'SNHD Protocols - Succinylcholine Calc');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (143, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 14 kg toddler with VF. Amiodarone: 14 kg × 5 mg/kg = ? mg IV/IO (max 300 mg)', E'["50 mg", "60 mg", "70 mg", "300 mg"]', 2, E'14 kg × 5 mg/kg = 70 mg IV/IO. Well under 300 mg max.', E'SNHD Protocols - Amiodarone Calc');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (144, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 65 kg adolescent in cardiac arrest needs amiodarone. 65 kg × 5 mg/kg = 325 mg. Apply max.', E'["300 mg (capped)", "325 mg", "350 mg", "400 mg"]', 0, E'Calculated 325 mg, but MAXIMUM is 300 mg. Give 300 mg IV/IO.', E'SNHD Protocols - Amiodarone Max');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (145, 'EMT', 'Pediatric', 'Medications', E'A 17 kg child has fever. Acetaminophen: 17 kg × 15 mg/kg = ? mg PO/PR', E'["200 mg", "255 mg", "300 mg", "350 mg"]', 1, E'17 kg × 15 mg/kg = 255 mg PO or PR (round to 240 mg or 260 mg per local protocol).', E'SNHD Protocols - Acetaminophen Calc');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (146, 'AEMT', 'Pediatric', 'Medications', E'A 6 kg infant is hypoglycemic. Dextrose gel: 6 kg × 0.5 g/kg = ? g (if awake)', E'["2 g", "3 g", "4 g", "5 g"]', 1, E'6 kg × 0.5 g/kg = 3 g oral glucose gel if awake with gag reflex.', E'SNHD Protocols - Oral Glucose');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (147, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 42 kg child needs ketamine for RSI. 42 kg × 2 mg/kg = ? mg IV', E'["60 mg", "74 mg", "84 mg", "100 mg"]', 2, E'42 kg × 2 mg/kg = 84 mg IV ketamine for induction.', E'SNHD Protocols - Ketamine Calc');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (148, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 25 kg child needs midazolam for seizure. 25 kg × 0.1 mg/kg = ? mg IM/IN (max 5 mg)', E'["2 mg", "2.5 mg", "3 mg", "5 mg"]', 1, E'25 kg × 0.1 = 2.5 mg IM/IN. Under 5 mg max. Can repeat in 5-10 minutes.', E'SNHD Protocols - Midazolam Calc');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (149, 'AEMT', 'Pediatric', 'Medications', E'A 10 kg child has allergic reaction. Diphenhydramine: 10 kg × 0.5 mg/kg = ? mg (max 25 mg)', E'["3 mg", "5 mg", "10 mg", "25 mg"]', 1, E'10 kg × 0.5 mg/kg = 5 mg IV/IM. Under 25 mg max.', E'SNHD Protocols - Diphenhydramine Calc');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (150, 'AEMT', 'Pediatric', 'Medications', E'A 3-year-old is wheezing but has a known sulfa allergy. Can you give albuterol?', E'["No - contraindicated", "Yes - albuterol is not a sulfa drug", "Only if severe", "Give epinephrine instead"]', 1, E'Albuterol does NOT contain sulfa. Safe to give despite sulfa allergy.', E'SNHD Protocols - Allergy Clarification');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (151, 'PARAMEDIC', 'Pediatric', 'Medications', E'A child needs pain control but has respiratory rate of 8. Which medication is CONTRAINDICATED?', E'["Acetaminophen", "Fentanyl", "Ketorolac", "Ibuprofen"]', 1, E'Fentanyl is contraindicated with respiratory depression (RR <10). Use non-opioid alternatives.', E'SNHD Protocols - Opioid Contraindications');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (152, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 2-year-old has SVT. Adenosine should be given:', E'["Rapid IV push with immediate flush", "Slow IV drip", "IM injection", "Subcutaneously"]', 0, E'Adenosine must be rapid IV push followed immediately by 5-10 mL saline flush (half-life <10 seconds).', E'SNHD Protocols - Adenosine Administration');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (153, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 20 kg child has moderate pain from a fracture. Ibuprofen dosing: 20 kg × 10 mg/kg = ?', E'["100 mg", "200 mg", "300 mg", "400 mg"]', 1, E'20 kg × 10 mg/kg = 200 mg PO ibuprofen (max 400 mg/dose, 1200 mg/day).', E'SNHD Protocols - Ibuprofen Dosing');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (154, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 15 kg toddler needs pain relief. Acetaminophen rectal: 15 kg × 15 mg/kg = ?', E'["150 mg", "200 mg", "225 mg", "300 mg"]', 2, E'15 kg × 15 mg/kg = 225 mg PR acetaminophen (round to 240 mg per local protocol).', E'SNHD Protocols - Acetaminophen PR');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (155, 'PARAMEDIC', 'Pediatric', 'Medications', E'An 18 kg child with vomiting. Ondansetron: 18 kg × 0.15 mg/kg = ? mg (max 4 mg)', E'["2 mg", "2.4 mg", "2.7 mg", "4 mg"]', 2, E'18 kg × 0.15 = 2.7 mg PO/ODT. Under 4 mg max. Can round to 2.5 or 3 mg.', E'SNHD Protocols - Ondansetron Dosing');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (156, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 25 kg child needs ondansetron. 25 kg × 0.15 = 3.75 mg. IV dosing is different:', E'["0.1 mg/kg IV (max 2 mg)", "0.15 mg/kg IV", "0.5 mg/kg IV", "1 mg/kg IV"]', 0, E'Ondansetron IV: 0.1 mg/kg (max 2 mg IV). PO/ODT is 0.15 mg/kg (max 4 mg).', E'SNHD Protocols - Ondansetron IV vs PO');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (157, 'EMT', 'Pediatric', 'Medications', E'A 12 kg infant with wheezing. Albuterol: 12 kg × 0.15 mg/kg = ? (min 2.5 mg)', E'["1.5 mg", "1.8 mg", "2.5 mg (minimum)", "3 mg"]', 2, E'12 kg × 0.15 = 1.8 mg, but MINIMUM is 2.5 mg. Give 2.5 mg via nebulizer.', E'SNHD Protocols - Albuterol Minimum');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (158, 'AEMT', 'Pediatric', 'Medications', E'Albuterol can be repeated every how often in severe pediatric asthma?', E'["Every 15 minutes", "Every 20-30 minutes", "Every hour", "Once only"]', 1, E'Albuterol can be repeated every 20-30 minutes in severe asthma with reassessment.', E'SNHD Protocols - Albuterol Frequency');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (159, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 20 kg child with moderate asthma exacerbation. Prednisolone: 20 kg × 1 mg/kg = ?', E'["10 mg", "20 mg", "30 mg", "40 mg"]', 1, E'20 kg × 1 mg/kg = 20 mg PO prednisolone (typical range 1-2 mg/kg).', E'SNHD Protocols - Prednisolone Dosing');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (160, 'PARAMEDIC', 'Pediatric', 'Medications', E'Dexamethasone for pediatric asthma/croup alternative dosing:', E'["0.3 mg/kg PO/IM (max 10 mg)", "0.6 mg/kg PO/IM (max 10 mg)", "1 mg/kg", "2 mg/kg"]', 1, E'Dexamethasone: 0.6 mg/kg PO/IM (max 10 mg) - longer acting than prednisolone.', E'SNHD Protocols - Dexamethasone');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (161, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 10 kg infant with opioid-induced respiratory depression. Naloxone: 10 kg × 0.1 mg/kg = ?', E'["0.5 mg", "1 mg", "1.5 mg", "2 mg"]', 1, E'10 kg × 0.1 mg/kg = 1 mg IV/IM/IN (max 2 mg). Titrate to effect, not full reversal.', E'SNHD Protocols - Naloxone Pediatric');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (162, 'PARAMEDIC', 'Pediatric', 'Medications', E'Naloxone for a 4-year-old (16 kg) with suspected overdose. Intranasal dosing?', E'["1 mg in one nostril", "2 mg total (1 mg each nostril)", "4 mg in one nostril", "0.5 mg total"]', 1, E'Pediatric IN naloxone: 2 mg total, divided as 1 mg in each nostril (max per nostril).', E'SNHD Protocols - Naloxone IN');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (163, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 3 kg newborn in cardiac arrest needs epinephrine. Dose: 3 kg × 0.01 mg/kg = ? mg IV/IO', E'["0.01 mg", "0.03 mg", "0.1 mg", "0.3 mg"]', 1, E'3 kg × 0.01 mg/kg = 0.03 mg (0.3 mL of 1:10,000) IV/IO every 3-5 minutes.', E'SNHD Protocols - Neonatal Epinephrine');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (164, 'PARAMEDIC', 'Pediatric', 'Medications', E'Pediatric epinephrine for cardiac arrest vs anaphylaxis dosing differs. Arrest is:', E'["0.01 mg/kg IV/IO (1:10,000)", "0.1 mg/kg IV/IO", "0.01 mg/kg IM", "0.3 mg fixed"]', 0, E'Cardiac arrest: 0.01 mg/kg (0.1 mL/kg) of 1:10,000 IV/IO. Anaphylaxis: 0.01 mg/kg IM (1:1,000).', E'SNHD Protocols - Epinephrine Routes');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (165, 'PARAMEDIC', 'Pediatric', 'Medications', E'Atropine for pediatric symptomatic bradycardia (minimum dose to prevent paradoxical bradycardia):', E'["0.01 mg/kg (min 0.1 mg, max 0.5 mg)", "0.02 mg/kg IV", "0.1 mg fixed", "0.5 mg fixed"]', 0, E'Atropine: 0.02 mg/kg IV/IO (minimum 0.1 mg, maximum 0.5 mg child, 1 mg adolescent).', E'SNHD Protocols - Atropine Pediatric');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (166, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 24 kg child needs RSI. Etomidate induction dose: 24 kg × 0.3 mg/kg = ? mg IV', E'["5 mg", "7.2 mg", "10 mg", "15 mg"]', 1, E'24 kg × 0.3 mg/kg = 7.2 mg IV etomidate for induction (typical range 0.2-0.3 mg/kg).', E'SNHD Protocols - Etomidate Pediatric');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (167, 'PARAMEDIC', 'Pediatric', 'Medications', E'Ketamine for pediatric sedation (not RSI): 30 kg × 1 mg/kg = ? mg IV/IM', E'["10 mg", "20 mg", "30 mg", "60 mg"]', 2, E'30 kg × 1 mg/kg = 30 mg IV/IM for procedural sedation (RSI dose is 2 mg/kg).', E'SNHD Protocols - Ketamine Sedation');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (168, 'PARAMEDIC', 'Pediatric', 'Medications', E'Propofol for pediatric RSI: 25 kg × 2 mg/kg = ? mg IV', E'["25 mg", "50 mg", "75 mg", "100 mg"]', 1, E'25 kg × 2 mg/kg = 50 mg IV propofol (use cautiously, can cause hypotension).', E'SNHD Protocols - Propofol Pediatric');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (169, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 20 kg child post-intubation needs ongoing paralysis. Vecuronium: 20 kg × 0.1 mg/kg = ?', E'["1 mg", "2 mg", "3 mg", "4 mg"]', 1, E'20 kg × 0.1 mg/kg = 2 mg IV vecuronium for maintenance paralysis.', E'SNHD Protocols - Vecuronium');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (170, 'PARAMEDIC', 'Pediatric', 'Medications', E'Post-intubation sedation for 40 kg child: Fentanyl 1 mcg/kg + Midazolam 0.1 mg/kg = ?', E'["20 mcg fentanyl + 2 mg midazolam", "40 mcg fentanyl + 4 mg midazolam", "60 mcg fentanyl + 6 mg midazolam", "100 mcg fentanyl + 10 mg midazolam"]', 1, E'40 kg: 40 mcg fentanyl + 4 mg midazolam. Both analgesia AND sedation required.', E'SNHD Protocols - Post-Intubation Care');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (171, 'AEMT', 'Pediatric', 'Medications', E'A 5 kg infant with BG 45 mg/dL and altered mental status. D10: 5 kg × 5 mL/kg = ?', E'["15 mL", "25 mL", "35 mL", "50 mL"]', 1, E'5 kg × 5 mL/kg = 25 mL D10 slow IV push for hypoglycemia.', E'SNHD Protocols - Infant Hypoglycemia');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (172, 'AEMT', 'Pediatric', 'Medications', E'Glucagon for a 12 kg child unable to take PO with BG 50: 12 kg × 0.03 mg/kg = ? mg IM', E'["0.2 mg", "0.36 mg", "0.5 mg", "1 mg"]', 1, E'12 kg × 0.03 mg/kg = 0.36 mg IM/SC glucagon (if no IV access, can use 0.5 mg min).', E'SNHD Protocols - Glucagon Pediatric');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (173, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 30 kg child with suspected meningitis. Ceftriaxone: 30 kg × 50 mg/kg = ? mg IM/IV', E'["500 mg", "1000 mg", "1500 mg", "2000 mg"]', 2, E'30 kg × 50 mg/kg = 1500 mg IM/IV ceftriaxone (max 2 g) for suspected meningitis.', E'SNHD Protocols - Meningitis Antibiotics');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (174, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 25 kg child with refractory asthma. Magnesium: 25 kg × 25-50 mg/kg = ? mg IV (max 2 g)', E'["250-500 mg", "625-1250 mg", "1000-1500 mg", "2000 mg"]', 1, E'25 kg × 25-50 mg/kg = 625-1250 mg IV magnesium sulfate over 20 minutes.', E'SNHD Protocols - Magnesium Asthma');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (175, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 20 kg child with hyperkalemia. Calcium gluconate: 20 kg × 0.5-1 mL/kg = ? mL', E'["5-10 mL", "10-20 mL", "20-30 mL", "30-40 mL"]', 1, E'20 kg × 0.5-1 mL/kg = 10-20 mL calcium gluconate slow IV for hyperkalemia/cardiac stabilization.', E'SNHD Protocols - Hyperkalemia');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (176, 'PARAMEDIC', 'Pediatric', 'Medications', E'A 15 kg child with severe metabolic acidosis. Sodium bicarb: 15 kg × 1-2 mEq/kg = ? mEq', E'["5-10 mEq", "15-30 mEq", "30-45 mEq", "45-60 mEq"]', 1, E'15 kg × 1-2 mEq/kg = 15-30 mEq sodium bicarbonate slow IV for severe acidosis.', E'SNHD Protocols - Bicarbonate');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (177, 'AEMT', 'Pediatric', 'Medications', E'A 22 kg child with allergic reaction. Diphenhydramine PO: 22 kg × 1 mg/kg = ? mg (max 50 mg)', E'["15 mg", "22 mg", "25 mg", "50 mg"]', 1, E'22 kg × 1 mg/kg = 22 mg PO diphenhydramine (IV/IM is 0.5 mg/kg, max 25 mg).', E'SNHD Protocols - Diphenhydramine PO');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (178, 'PARAMEDIC', 'Pediatric', 'Medications', E'A child with organophosphate poisoning needs atropine. Initial dose and escalation?', E'["0.01 mg/kg once", "0.02 mg/kg, double every 5 min until secretions dry", "0.1 mg/kg single dose", "1 mg fixed regardless of weight"]', 1, E'Organophosphate: 0.02 mg/kg atropine, double every 5 min until drying of secretions (toxic dose may be very high).', E'SNHD Protocols - Organophosphate');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (179, 'EMT', 'Pediatric', 'Medications', E'Broselow tape color zones estimate weights. Yellow zone is approximately:', E'["3-5 kg", "10-11 kg", "15-18 kg", "24-29 kg"]', 1, E'Broselow tape: Yellow = 10-11 kg (approximately 1 year old).', E'SNHD Protocols - Broselow Reference');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (180, 'EMT', 'Pediatric', 'Medications', E'Using Broselow tape, Purple zone (smallest) equipment sizes and approximate weight:', E'["Premature <3 kg", "Term newborn 3-5 kg", "3-6 months 5-7 kg", "6-12 months 8-10 kg"]', 1, E'Broselow Purple = term newborn approximately 3-5 kg.', E'SNHD Protocols - Broselow Purple');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (181, 'EMT', 'Pediatric', 'Fluid Boluses', E'What is the standard weight-based volume for an initial NS or LR bolus in pediatric patients according to the Clark County protocols?', E'["30 ml/kg", "20 ml/kg", "10 ml/kg", "50 ml/kg"]', 1, E'20 ml/kg is the fundamental weight-based fluid increment for pediatric patients across most shock and assessment protocols.', E'SNHD Protocols - Pediatric Fluids');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (182, 'EMT', 'Pediatric', 'Fluid Boluses', E'What is the maximum total volume of NS or LR that should be administered to a pediatric patient in shock before seeking medical direction?', E'["100 ml/kg", "40 ml/kg", "20 ml/kg", "60 ml/kg"]', 1, E'Maximum 40 ml/kg (2 boluses) before seeking medical direction or considering other interventions.', E'SNHD Protocols - Pediatric Shock Limits');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (183, 'AEMT', 'Pediatric', 'Fluid Boluses', E'If a pediatric patient with abdominal pain is suspected of being in Diabetic Ketoacidosis (DKA), what is the maximum amount of fluid bolus allowed?', E'["20 ml/kg", "10 ml/kg", "60 ml/kg", "40 ml/kg"]', 1, E'DKA patients get maximum 10 ml/kg bolus due to risk of cerebral edema.', E'SNHD Protocols - Pediatric DKA');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (184, 'EMT', 'Pediatric', 'Fluid Boluses', E'According to the Pediatric Burn protocol, what is the appropriate fluid bolus for a 4-year-old child showing signs of hypoperfusion?', E'["250 ml", "125 ml", "500 ml", "20 ml/kg"]', 3, E'Pediatric burn protocol uses 20 ml/kg for hypoperfusion, not fixed volumes.', E'SNHD Protocols - Pediatric Burn');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (185, 'EMT', 'Pediatric', 'Fluid Boluses', E'In the Pediatric Burn protocol, what is the fixed bolus volume for a 10-year-old child?', E'["1000 ml", "125 ml", "500 ml", "250 ml"]', 2, E'Pediatric burn protocol specifies 500 ml fixed bolus for certain age groups with hypoperfusion.', E'SNHD Protocols - Pediatric Burn Fixed');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (186, 'EMT', 'Pediatric', 'Fluid Boluses', E'For a 15-year-old patient being treated under the Pediatric Burn protocol, what fluid bolus should be administered?', E'["20 ml/kg", "500 ml", "1000 ml", "250 ml"]', 1, E'500 ml bolus for pediatric burn patients in specific age/weight categories.', E'SNHD Protocols - Pediatric Burn');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (187, 'EMT', 'Pediatric', 'Assessment', E'What is the calculated minimum acceptable systolic blood pressure for a 5-year-old child?', E'["90 mmHg", "70 mmHg", "100 mmHg", "80 mmHg"]', 3, E'Using formula (Age × 2) + 70: (5 × 2) + 70 = 80 mmHg minimum SBP.', E'SNHD Protocols - Pediatric BP Calculation');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (188, 'AEMT', 'Pediatric', 'Fluid Boluses', E'When treating a pediatric patient for non-traumatic shock, which clinical finding indicates that you should stop repeating fluid boluses?', E'["A systolic blood pressure of 70 mmHg in a 1-year-old", "The patient remains tachycardic", "Presence of rales on lung exam", "The patient develops a fever"]', 2, E'Rales on lung exam indicates fluid overload - stop fluids and contact medical direction.', E'SNHD Protocols - Fluid Contraindications');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (189, 'EMT', 'Pediatric', 'Assessment', E'What is the minimum systolic blood pressure target for a 2-year-old child undergoing fluid resuscitation?', E'["72 mmHg", "74 mmHg", "80 mmHg", "90 mmHg"]', 1, E'Using formula (Age × 2) + 70: (2 × 2) + 70 = 74 mmHg minimum SBP.', E'SNHD Protocols - Pediatric BP Target');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (190, 'AEMT', 'Fluid Boluses', 'Assessment', E'Which fluid types are approved for bolus administration in both adult and pediatric patients according to these protocols?', E'["NS with 20 mEq/L Potassium", "D5W or NS", "NS or LR", "0.45% NS only"]', 2, E'Normal Saline (NS) or Lactated Ringers (LR) are approved for boluses in all patients.', E'SNHD Protocols - Approved Fluids');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (191, 'EMT', 'Environmental', 'Environmental', E'For adult patients suffering from heat-related or cold-related illness with poor perfusion, what is the initial bolus volume?', E'["2000 ml", "500 ml", "1000 ml", "250 ml"]', 1, E'500 ml bolus for environmental illness with poor perfusion in adults.', E'SNHD Protocols - Environmental Illness');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (192, 'EMT', 'Environmental', 'Environmental', E'What is the maximum cumulative fluid limit for an adult patient being treated for Heat-Related illness?', E'["3000 ml", "60 ml/kg", "1000 ml", "2000 ml"]', 3, E'Maximum 2000 ml cumulative for heat-related illness in adults.', E'SNHD Protocols - Heat Illness Limits');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (193, 'EMT', 'Other', 'Assessment', E'According to the general assessment Pearls, what action must be performed after each fluid bolus is administered?', E'["Administer an antiemetic", "Perform retroperitoneal palpation", "Check a blood glucose level", "Repeat vital signs"]', 3, E'Repeat vital signs after every fluid bolus to assess response and avoid fluid overload.', E'SNHD Protocols - Assessment Pearls');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (194, 'PARAMEDIC', 'Pediatric', 'Cardiac/Respiratory', E'In the case of pediatric bradycardia with poor perfusion, what fluid intervention is indicated if hypovolemia is suspected?', E'["No fluid bolus is indicated for bradycardia", "10 ml/kg bolus", "D10 at 5 ml/kg", "20 ml/kg bolus"]', 3, E'Pediatric bradycardia with poor perfusion gets 20 ml/kg bolus if hypovolemia suspected after oxygenation/ventilation.', E'SNHD Protocols - Pediatric Bradycardia');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (195, 'EMT', 'Pediatric', 'Medications', E'Which protocol specifies that Morphine is not recommended for children?', E'["Neonatal Resuscitation", "Pediatric Allergic Reaction", "Pediatric Burns", "Pediatric Abdominal Pain"]', 2, E'Pediatric Burn protocol specifies morphine is not recommended for children.', E'SNHD Protocols - Pediatric Burns');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (196, 'EMT', 'Pediatric', 'Environmental', E'For a pediatric smoke inhalation patient with hypotension, what is the appropriate initial fluid management?', E'["NS or LR bolus at 125 ml", "NS or LR bolus at 20 ml/kg", "NS bolus at 500 ml", "Hydroxocobalamin only"]', 1, E'Pediatric smoke inhalation with hypotension gets 20 ml/kg NS or LR bolus.', E'SNHD Protocols - Smoke Inhalation');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (197, 'EMT', 'Pediatric', 'Fluid Boluses', E'What is the maximum cumulative dose for fluid boluses in the Pediatric Allergic Reaction protocol for a patient in shock?', E'["2000 ml", "60 ml/kg", "30 ml/kg", "20 ml/kg"]', 3, E'Pediatric Allergic Reaction protocol limits fluids to maximum 20 ml/kg for shock.', E'SNHD Protocols - Pediatric Allergic Reaction');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (198, 'PARAMEDIC', 'Pediatric', 'Medications', E'For patients with known adrenal insufficiency, what is the primary recommended intervention alongside fluid boluses?', E'["Oral glucose regardless of BG level", "Administer high-dose Epinephrine", "Wait for medical direction", "Administer the patient''s own Solu-Cortef"]', 3, E'Patients with adrenal insufficiency should receive their own Solu-Cortef (hydrocortisone) if available.', E'SNHD Protocols - Adrenal Insufficiency');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (199, 'EMT', 'Pediatric', 'Assessment', E'The estimated minimum systolic blood pressure calculation formula ((Age in Years×2)+70) applies up to what age?', E'["5 years", "18 years", "10 years", "13 years"]', 1, E'Formula (Age × 2) + 70 applies up to age 18. Adult minimum (90 mmHg) applies after age 18.', E'SNHD Protocols - BP Formula Age');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (200, 'EMT', 'OB/Neonatal', 'Procedures', E'In Neonatal Resuscitation, what is the required compression-to-ventilation ratio for CPR?', E'["10:1", "15:2", "3:1", "30:2"]', 2, E'Neonatal CPR uses 3:1 compression-to-ventilation ratio (3 compressions, 1 breath).', E'SNHD Protocols - Neonatal CPR');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (201, 'EMT', 'OB/Neonatal', 'Medications', E'What dose of D10 is specified for a newborn with hypoglycemia (BG<40 mg/dl)?', E'["5 ml/kg", "10 ml/kg", "2 ml/kg", "20 ml/kg"]', 0, E'Neonatal hypoglycemia: D10 at 5 ml/kg IV/IO.', E'SNHD Protocols - Neonatal Hypoglycemia');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (202, 'EMT', 'OB/Neonatal', 'Assessment', E'What threshold defines hypoglycemia in a newborn according to the protocols?', E'["<60 mg/dl", "<20 mg/dl", "<80 mg/dl", "<40 mg/dl"]', 3, E'Newborn hypoglycemia is defined as blood glucose <40 mg/dl.', E'SNHD Protocols - Neonatal Glucose');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (203, 'PARAMEDIC', 'OB/Neonatal', 'Medications', E'Which concentration of Sodium Bicarbonate should be used for neonatal patients according to the protocols?', E'["0.45%", "5%", "8.4%", "4.2%"]', 3, E'Neonates should receive 4.2% sodium bicarbonate (diluted from 8.4%).', E'SNHD Protocols - Neonatal Bicarbonate');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (204, 'PARAMEDIC', 'Burns', 'Procedures', E'What is the primary reason to contact Medical Direction at the Burn Center according to the tiered burn protocols?', E'["For further drip rates or additional boluses", "To confirm the patient''s age", "To report blood glucose levels", "To request an initial fluid bolus"]', 0, E'Contact Burn Center Medical Direction for further drip rates or additional boluses beyond initial protocol.', E'SNHD Protocols - Burn Center Contact');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (205, 'AEMT', 'Pediatric', 'Medications', E'In the Pediatric Allergic Reaction protocol, what is the maximum single dose of Diphenhydramine?', E'["1 mg", "50 mg", "25 mg", "100 mg"]', 1, E'Maximum single dose of diphenhydramine in pediatric allergic reaction is 50 mg.', E'SNHD Protocols - Pediatric Diphenhydramine');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (206, 'PARAMEDIC', 'Pediatric', 'Medications', E'What is the maximum single dose of D10 when treating a pediatric patient for hypoglycemia?', E'["60 ml", "25 g", "50 g", "5 g"]', 1, E'Maximum single dose of D10 for pediatric hypoglycemia is 25 grams.', E'SNHD Protocols - D10 Maximum');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (207, 'AEMT', 'Pediatric', 'Medications', E'What is the appropriate dose of Glucagon for a pediatric patient with no IV access who weighs less than 20 kg?', E'["0.5 mg IM", "0.1 mg/kg IM", "0.01 mg/kg IM", "1 mg IM"]', 0, E'Glucagon for pediatrics <20 kg without IV access: 0.5 mg IM.', E'SNHD Protocols - Glucagon Pediatric');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (208, 'AEMT', 'Pediatric', 'Medications', E'According to the Pediatric Allergic Reaction protocol, what is the maximum single dose of Epinephrine 1:1000 that can be administered IM?', E'["0.5 mg", "1.5 mg", "0.3 mg", "0.1 mg"]', 2, E'Maximum single dose of Epinephrine 1:1000 IM for pediatric allergic reaction is 0.3 mg.', E'SNHD Protocols - Pediatric Epi Max');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (209, 'EMT', 'Pediatric', 'Medications', E'In a pediatric patient with suspected hypoglycemia, what is the correct volume and concentration for a D10 IV/IO bolus?', E'["2 ml/kg of D10", "5 ml/kg of D10", "25 ml/kg of D10", "10 ml/kg of D10"]', 1, E'Pediatric hypoglycemia: D10 at 5 ml/kg IV/IO bolus.', E'SNHD Protocols - Pediatric D10');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (210, 'AEMT', 'Pediatric', 'Medications', E'What is the weight-based dose for Diphenhydramine (Benadryl) across pediatric protocols for allergic reactions and dystonic reactions?', E'["0.5 mg/kg", "5 mg/kg", "1 mg/kg", "2 mg/kg"]', 2, E'Pediatric diphenhydramine: 1 mg/kg PO or 0.5 mg/kg IV/IM for allergic/dystonic reactions.', E'SNHD Protocols - Diphenhydramine Dosing');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (211, 'PARAMEDIC', 'Pediatric', 'Medications', E'Which of the following is the maximum single dose for IV Morphine in pediatric pain management?', E'["2 mg", "5 mg", "15 mg", "10 mg"]', 0, E'Maximum single dose of IV Morphine for pediatric pain management is 2 mg.', E'SNHD Protocols - Pediatric Morphine');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (212, 'PARAMEDIC', 'Pediatric', 'Medications', E'What is the recommended dose for Push Dose Epinephrine in the treatment of pediatric shock?', E'["1 mcg/kg", "0.01 mg/kg", "0.1 mcg/kg", "0.1 mg/kg"]', 0, E'Push dose epinephrine for pediatric shock: 1 mcg/kg IV/IO.', E'SNHD Protocols - Push Dose Epi');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (213, 'PARAMEDIC', 'Pediatric', 'Medications', E'For a pediatric patient in SVT, what is the initial rapid IV/IO push dose of Adenosine?', E'["0.2 mg/kg", "0.1 mg/kg", "6 mg fixed dose", "0.3 mg/kg"]', 1, E'Pediatric SVT: Initial adenosine 0.1 mg/kg rapid IV/IO push (max 6 mg first dose).', E'SNHD Protocols - Pediatric Adenosine');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (214, 'PARAMEDIC', 'Pediatric', 'Medications', E'When administering Naloxone (Narcan) titration to a pediatric patient with respiratory depression, what is the per-kilogram dose?', E'["2 mg fixed dose", "0.5 mg/kg", "0.01 mg/kg", "0.1 mg/kg"]', 3, E'Pediatric naloxone titration: 0.1 mg/kg IV/IM/IN (titrate to respiratory effort, not full consciousness).', E'SNHD Protocols - Naloxone Titration');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (215, 'PARAMEDIC', 'Pediatric', 'Medications', E'What is the maximum single dose of Fentanyl for a pediatric patient without a physician order?', E'["50 mcg", "10 mcg", "200 mcg", "100 mcg"]', 0, E'Maximum single dose of fentanyl for pediatric patients without physician order is 50 mcg.', E'SNHD Protocols - Fentanyl Max');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (216, 'PARAMEDIC', 'Pediatric', 'Medications', E'Under the Pediatric Seizure protocol, what is the dose for Midazolam when treating an active seizure?', E'["0.2 mg/kg", "0.05 mg/kg", "2.5 mg fixed dose", "0.1 mg/kg"]', 3, E'Pediatric seizure: Midazolam 0.1 mg/kg IM/IN/IV (max 5 mg).', E'SNHD Protocols - Midazolam Seizure');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (217, 'PARAMEDIC', 'Pediatric', 'Medications', E'What is the specific age requirement for administering Metoclopramide (Reglan) to a pediatric patient for nausea or pain?', E'["8 years of age or older", "12 years of age or older", "10 years of age or older", "2 years of age or older"]', 0, E'Metoclopramide (Reglan) is only for pediatric patients 8 years or older.', E'SNHD Protocols - Reglan Age');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (218, 'PARAMEDIC', 'Pediatric', 'Medications', E'What is the correct dose for IV Acetaminophen (Tylenol) in pediatric patients?', E'["1 g fixed dose", "15 mg/kg", "10 mg/kg", "0.15 mg/kg"]', 1, E'IV Acetaminophen for pediatrics: 15 mg/kg (max adult dose).', E'SNHD Protocols - IV Tylenol');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (219, 'PARAMEDIC', 'Pediatric', 'Medications', E'In pediatric bradycardia, what are the minimum and maximum single doses for Atropine?', E'["Min: 0.5 mg; Max: 3 mg", "Min: 0.1 mg; Max: 0.5 mg", "Min: 0.1 mg; Max: 1 mg", "Min: 0.02 mg; Max: 1 mg"]', 2, E'Pediatric atropine: Minimum 0.1 mg (to prevent paradoxical bradycardia), Maximum 0.5 mg child / 1 mg adolescent.', E'SNHD Protocols - Atropine Min/Max');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (220, 'PARAMEDIC', 'Pediatric', 'Medications', E'What is the pediatric dose for Ondansetron (Zofran)?', E'["4 mg fixed dose", "0.1 mg/kg", "1 mg/kg", "0.15 mg/kg"]', 3, E'Pediatric ondansetron: 0.15 mg/kg PO/ODT (max 4 mg) or 0.1 mg/kg IV (max 2 mg).', E'SNHD Protocols - Ondansetron Dose');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (221, 'PARAMEDIC', 'Pediatric', 'Medications', E'According to the Tachycardia protocol, how is Amiodarone administered to a pediatric patient with a pulse?', E'["150 mg over 10 minutes", "5 mg/kg rapid IV push", "5 mg/kg in 50 ml NS over 20 minutes", "0.2 mg/kg over 20 minutes"]', 2, E'Amiodarone with pulse: 5 mg/kg in 50 ml NS over 20 minutes (slow infusion).', E'SNHD Protocols - Amiodarone With Pulse');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (222, 'PARAMEDIC', 'Pediatric', 'Medications', E'What is the maximum dose of Midazolam allowed for the management of a pediatric febrile seizure?', E'["10 mg", "2.5 mg", "5 mg", "1 mg"]', 2, E'Maximum midazolam for pediatric febrile seizure is 5 mg.', E'SNHD Protocols - Midazolam Max Seizure');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (223, 'PARAMEDIC', 'Pediatric', 'Medications', E'When performing pediatric intubation, what is the induction dose for Etomidate?', E'["0.03 mg/kg", "0.3 mg/kg", "1 mg/kg", "0.15 mg/kg"]', 1, E'Pediatric etomidate for RSI induction: 0.3 mg/kg IV.', E'SNHD Protocols - Etomidate RSI');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (224, 'PARAMEDIC', 'Pediatric', 'Medications', E'Which concentration and dose of Epinephrine is administered via the Endotracheal Tube (ETT) during pediatric bradycardia?', E'["1:1000, 0.1 mg/kg", "1:10,000, 0.01 mg/kg", "1:1000, 0.01 mg/kg", "1:10,000, 0.1 mg/kg"]', 0, E'ETT epinephrine: 1:1000 concentration at 0.1 mg/kg (higher concentration for ETT route).', E'SNHD Protocols - ETT Epinephrine');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (225, 'PARAMEDIC', 'Pediatric', 'Medications', E'What is the maximum single dose of Naloxone (Narcan) when administered via the Intranasal (IN) route to a pediatric patient?', E'["0.5 mg", "4 mg", "0.1 mg", "10 mg"]', 1, E'Maximum single IN naloxone dose for pediatrics is 4 mg (2 mg per nostril).', E'SNHD Protocols - Naloxone IN Max');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (226, 'PARAMEDIC', 'Pediatric', 'Medications', E'Under the Pediatric Tachycardia protocol, what is the dose for Magnesium Sulfate in cases of Torsades de Pointes?', E'["2 g fixed dose", "5 mg/kg over 20 minutes", "50 mg/kg rapid IV push", "25 mg/kg in 50 ml NS over 10 minutes"]', 3, E'Magnesium for pediatric Torsades: 25-50 mg/kg (max 2 g) over 10-20 minutes.', E'SNHD Protocols - Magnesium Torsades');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (227, 'PARAMEDIC', 'Pediatric', 'Medications', E'For pediatric induction during airway management, what is the IV/IO dose for Ketamine?', E'["4 mg/kg", "0.3 mg/kg", "2 mg/kg", "1 mg/kg"]', 2, E'Pediatric ketamine for RSI induction: 2 mg/kg IV/IO.', E'SNHD Protocols - Ketamine RSI');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (228, 'PARAMEDIC', 'Pediatric', 'Medications', E'What is the maximum single dose of Ketamine when administered via the IM route for induction?', E'["500 mg", "200 mg", "100 mg", "400 mg"]', 0, E'Maximum single IM ketamine dose for pediatric induction is 500 mg.', E'SNHD Protocols - Ketamine IM Max');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (229, 'PARAMEDIC', 'Pediatric', 'Medications', E'In the Pediatric Shock protocol, for a patient with known adrenal insufficiency, what medication should be administered?', E'["0.1 mg/kg Dexamethasone", "The patient''s own Solu-Cortef (hydrocortisone)", "2 mg/kg Methylprednisolone", "0.01 mg/kg Epinephrine"]', 1, E'Adrenal insufficiency: Give patient''s own Solu-Cortef (hydrocortisone) if available.', E'SNHD Protocols - Adrenal Insufficiency');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (230, 'EMT', 'Pediatric', 'Fluid Boluses', E'What is the initial volume for a pediatric fluid bolus in a non-trauma shock patient, provided there are no rales on lung exam?', E'["60 ml/kg", "20 ml/kg", "500 ml", "10 ml/kg"]', 1, E'Initial pediatric fluid bolus for non-trauma shock: 20 ml/kg (if no rales/JVD).', E'SNHD Protocols - Initial Bolus');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (231, 'AEMT', 'Pediatric', 'Medications', E'What is the maximum cumulative dose of Epinephrine 1:1000 that can be given IM for a pediatric allergic reaction?', E'["0.5 mg", "1.0 mg", "1.5 mg", "3.0 mg"]', 1, E'Maximum cumulative IM epinephrine 1:1000 for pediatric allergic reaction is 1.0 mg.', E'SNHD Protocols - Epi Cumulative Max');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (232, 'PARAMEDIC', 'Pediatric', 'Medications', E'In the Pediatric Pain Management protocol, what is the IN/IM/IV/IO dose for Fentanyl?', E'["1 mcg/kg", "0.1 mcg/kg", "1 mg/kg", "10 mcg/kg"]', 0, E'Pediatric fentanyl: 1 mcg/kg IN/IM/IV/IO (max 50 mcg without physician order).', E'SNHD Protocols - Fentanyl Dosing');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (233, 'PARAMEDIC', 'Pediatric', 'Medications', E'Under the Post-Intubation Sedation protocol for pediatrics, what is the maximum single dose of Midazolam?', E'["20 mg", "2.5 mg", "5 mg", "10 mg"]', 1, E'Maximum single midazolam dose for pediatric post-intubation sedation is 2.5 mg.', E'SNHD Protocols - Post-Intubation Midazolam');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (234, 'PARAMEDIC', 'Pediatric', 'Medications', E'What is the correct concentration and dose of Epinephrine used for IV/IO administration in pediatric bradycardia or cardiac arrest?', E'["1:10,000, 0.01 mg/kg", "1:1000, 0.01 mg/kg", "1:10,000, 0.1 mg/kg", "1:1000, 0.1 mg/kg"]', 0, E'IV/IO epinephrine: 1:10,000 concentration at 0.01 mg/kg (0.1 ml/kg).', E'SNHD Protocols - Epi IV/IO');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (235, 'EMT', 'Pediatric', 'Medications', E'What is the recommended dose of Ipratropium (0.02%) for a pediatric patient over 2 years old with wheezing?', E'["2.5 ml", "5 ml", "0.5 mg", "3.0 ml"]', 0, E'Ipratropium 0.02% for pediatrics >2 years: 2.5 ml via SVN.', E'SNHD Protocols - Ipratropium');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (236, 'EMT', 'Pediatric', 'Medications', E'Which medication is noted as ''not recommended'' for children in the treatment of pediatric abdominal pain?', E'["Ondansetron", "Morphine", "Fentanyl", "Acetaminophen"]', 1, E'Morphine is specifically noted as NOT recommended for children with abdominal pain.', E'SNHD Protocols - Abdominal Pain Meds');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (237, 'EMT', 'Pediatric', 'Assessment', E'According to the General Pediatric Assessment pearls, what is the standard initial fluid bolus for a pediatric patient in Clark County?', E'["20 ml/kg", "50 ml/kg", "30 ml/kg", "10 ml/kg"]', 0, E'Standard initial pediatric fluid bolus in Clark County protocols is 20 ml/kg.', E'SNHD Protocols - Assessment Pearls');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (238, 'AEMT', 'Pediatric', 'Medications', E'For a pediatric patient with suspected hypoglycemia who weighs less than 20 kg, what is the correct dosage of Glucagon (IM)?', E'["0.5 mg", "2 mg", "1 mg", "0.1 mg/kg"]', 0, E'Glucagon for pediatrics <20 kg: 0.5 mg IM (if no IV access).', E'SNHD Protocols - Glucagon <20kg');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (239, 'EMT', 'Pediatric', 'Fluid Boluses', E'What is the maximum total volume of fluid boluses a pediatric patient can receive under general assessment pearls?', E'["20 ml/kg", "100 ml/kg", "40 ml/kg", "60 ml/kg"]', 2, E'Maximum total fluid boluses under general assessment pearls: 40 ml/kg.', E'SNHD Protocols - Max Fluids');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (240, 'AEMT', 'Pediatric', 'Fluid Boluses', E'In a pediatric patient suspected of having Diabetic Ketoacidosis (DKA), what is the maximum fluid bolus limit specified?', E'["Do not exceed 10 ml/kg", "No limit is specified for DKA", "Do not exceed 20 ml/kg", "Do not exceed 60 ml/kg"]', 0, E'DKA maximum fluid bolus: Do not exceed 10 ml/kg due to cerebral edema risk.', E'SNHD Protocols - DKA Max');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (241, 'AEMT', 'Pediatric', 'Medications', E'When managing a pediatric allergic reaction, what is the maximum single dose of Epinephrine 1:1000 given via the IM route?', E'["1.0 mg", "0.3 mg", "1.5 mg", "0.5 mg"]', 1, E'Maximum single IM dose of Epinephrine 1:1000 for pediatric allergic reaction is 0.3 mg.', E'SNHD Protocols - Epi IM Max');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (242, 'EMT', 'Pediatric', 'Assessment', E'At what blood glucose level is a newborn considered hypoglycemic according to the Pediatric Altered Mental Status protocol?', E'["<70 mg/dl", "<40 mg/dl", "<20 mg/dl", "<60 mg/dl"]', 1, E'Newborn hypoglycemia threshold: <40 mg/dl.', E'SNHD Protocols - Newborn Hypoglycemia');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (243, 'PARAMEDIC', 'Pediatric', 'Medications', E'What is the maximum single dose of D10 permitted for a pediatric patient?', E'["25 g", "50 g", "10 g", "15 g"]', 0, E'Maximum single dose of D10 for pediatric hypoglycemia is 25 grams.', E'SNHD Protocols - D10 Max Single');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (244, 'EMT', 'Pediatric', 'Assessment', E'Which sign is specifically used to identify the onset of puberty in a female patient to determine if adult protocols should be used?', E'["First menstrual cycle", "Height over 5 feet", "Age over 12 years", "Any breast development"]', 3, E'Any breast development indicates onset of puberty in females - may use adult protocols.', E'SNHD Protocols - Puberty Assessment');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (245, 'AEMT', 'Pediatric', 'Medications', E'What is the maximum dose of Diphenhydramine for a pediatric patient experiencing an allergic reaction?', E'["100 mg", "25 mg", "75 mg", "50 mg"]', 3, E'Maximum diphenhydramine dose for pediatric allergic reaction is 50 mg.', E'SNHD Protocols - Diphenhydramine Max');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (246, 'EMT', 'Pediatric', 'Other', E'What is the appropriate size BVM for a pediatric patient weighing 25 kg?', E'["Infant BVM", "Pediatric BVM", "Neonatal BVM", "Adult BVM"]', 1, E'Pediatric BVM is appropriate for patients approximately 10-40 kg (child size).', E'SNHD Protocols - BVM Sizing');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (247, 'PARAMEDIC', 'Pediatric', 'Medications', E'When using Ondansetron ODT to a child, how should the provider handle rounding the dose?', E'["Round up to the nearest 1/2 pill", "Round down to the nearest whole pill", "Do not round, administer exact weight-based dose", "Round to the nearest 1/4 pill"]', 1, E'Round down to nearest whole pill to avoid overdose.', E'SNHD Protocols - Ondansetron Rounding');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (248, 'EMT', 'Pediatric', 'Other', E'What is the weight range for using a Pediatric BVM according to the Cardiac Arrest pearls?', E'["Under 10 kg", "10 to 40 kg", "5 to 30 kg", "5 to 20 kg"]', 1, E'Pediatric BVM is for patients approximately 10-40 kg.', E'SNHD Protocols - Pediatric BVM Range');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (249, 'EMT', 'Pediatric', 'Medications', E'Which medication is NOT recommended for use in children for behavioral emergencies in Clark County?', E'["Naloxone", "Albuterol", "Midazolam", "Diphenhydramine"]', 2, E'Midazolam is NOT recommended for pediatric behavioral emergencies per Clark County protocols.', E'SNHD Protocols - Behavioral Meds');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (250, 'EMT', 'Pediatric', 'Medications', E'What is the recommended dose of Levalbuterol for a pediatric patient via SVN?', E'["0.63 mg", "2.5 mg", "1.25 mg", "5.0 mg"]', 2, E'Levalbuterol pediatric dose: 1.25 mg via SVN.', E'SNHD Protocols - Levalbuterol');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (251, 'AEMT', 'Pediatric', 'Medications', E'Which of these is a strict ''never'' rule regarding Epinephrine administration for allergic reactions?', E'["Never use an auto-injector on a child", "Never give Epinephrine to a child under 5 kg", "Never give Epinephrine 1:1000 (IM concentration) through IV/IO route", "Never repeat Epinephrine more than once"]', 2, E'NEVER give Epinephrine 1:1000 (IM concentration) via IV/IO - must use 1:10,000 for IV/IO.', E'SNHD Protocols - Epi Safety');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (252, 'PARAMEDIC', 'Pediatric', 'Medications', E'For a pediatric patient in shock, what is the goal systolic blood pressure (SBP) when titrating push-dose epinephrine or fluids?', E'["60+Age", "70+2\\u00d7Age", "Always 100 mm Hg", "90+2\\u00d7Age"]', 1, E'Goal SBP for pediatric shock: 70 + (2 × Age in years).', E'SNHD Protocols - SBP Goal');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (253, 'EMT', 'Pediatric', 'Assessment', E'When managing pediatric epistaxis, what is the first step according to the assessment flow?', E'["General Pediatric Assessment", "Administer Oxymetazoline", "Apply an ice pack to the bridge of the nose", "Direct pressure for 15 minutes"]', 0, E'First step in pediatric epistaxis is General Pediatric Assessment.', E'SNHD Protocols - Epistaxis');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (254, 'EMT', 'Pediatric', 'Other', E'What is the weight threshold for switching from an Infant BVM to a Pediatric BVM?', E'["5 kg", "3 kg", "10 kg", "15 kg"]', 0, E'Switch from Infant to Pediatric BVM at approximately 5 kg.', E'SNHD Protocols - BVM Switch');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (255, 'AEMT', 'Medications', 'Procedures', E'What is the action of Benadryl?', E'["Beta agonist", "Antihistamine", "Vasoconstrictor", "Analgesic"]', 1, E'Diphenhydramine (Benadryl) is an antihistamine', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (256, 'AEMT', 'Medications', 'Other', E'What class of medication is glucagon?', E'["Sympathomimetic", "Hormone/Hyperglycemic agent", "Anticholinergic", "Electrolyte"]', 1, E'Glucagon is a hormone that acts as a hyperglycemic agent', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (257, 'AEMT', 'OB/Neonatal', 'OB/Neonatal', E'What score does grimace get on the APGAR scale?', E'["0-2", "1-5", "0-10", "1-3"]', 0, E'Grimace (Reflex Irritability) is scored from 0 to 2 on the APGAR scale', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (258, 'AEMT', 'Transport Criteria', 'Transport/Admin', E'Which hospital does air transport go?', E'["Nearest hospital", "Trauma Center/Specialty Center", "Any hospital with a helipad", "Airport"]', 1, E'Air transport typically goes to appropriate Trauma or Specialty Centers based on patient needs', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (259, 'AEMT', 'Pediatric', 'Other', E'A 6 year old with 15% 2nd and 3rd degree TBSA burns should get what bolus of NS or LR?', E'["10 mL/kg", "20 mL/kg", "500 mL", "None"]', 2, E'Protocol for pediatric burns >10% TBSA (age 6-12) often uses a specific fluid table or formula but general pediatric shock bolus is 20ml/kg', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (260, 'AEMT', 'Pediatric', 'Medications', E'What naloxone dose should you give a pediatric patient that weighs 20kg who has taken her mother''s pain meds?', E'["0.1 mg/kg", "2 mg", "10 mg", "0.5 mg"]', 0, E'Pediatric Naloxone dose is 0.1 mg/kg', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (261, 'AEMT', 'Medications', 'Other', E'Ondansetron is which class of medication?', E'["Analgesic", "Antiemetic", "Antibiotic", "Sedative"]', 1, E'Ondansetron is an antiemetic', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (262, 'AEMT', 'Trauma', 'Scoring', E'What trauma field triage criteria does pelvic fracture go into?', E'["Step 1", "Step 2", "Step 3", "Step 4"]', 1, E'Pelvic fractures are typically Step 2 (Anatomic) criteria', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (263, 'AEMT', 'Fluid Boluses', 'Adult', E'An adult male with non-traumatic abdominal pain is hypovolemic what is the correct initial bolus dose?', E'["250 mL", "500 mL", "1000 mL", "2000 mL"]', 1, E'For non-traumatic hypovolemia/shock initial bolus is often 500 mL', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (264, 'AEMT', 'Medications', '', E'An expected side effect after administering a bronchodilator would be?', E'["Bradycardia", "Tachycardia/Tremors", "Hypotension", "Sedation"]', 1, E'Bronchodilators like Albuterol commonly cause tachycardia and tremors', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (265, 'AEMT', 'Transport Criteria', 'Pediatric', E'Where should a sexual assault victim under 13 years old be transported?', E'["UMC", "Sunrise", "St. Rose Siena", "Summerlin"]', 1, E'Pediatric sexual assault victims (<13) are typically transported to Sunrise Hospital', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (266, 'AEMT', 'Transport Criteria', 'Trauma/Emergencies', E'How high should you raise the head of the bed for a patient with suspected brain injury?', E'["0 degrees", "15 degrees", "30 degrees", "45 degrees"]', 2, E'Head of bed should be elevated 30 degrees for TBI to reduce ICP', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (267, 'AEMT', 'Medications', 'Procedures', E'How low should BGL be before D10 is administered?', E'["<40 mg/dL", "<60 mg/dL", "<80 mg/dL", "<100 mg/dL"]', 1, E'D10 is administered for BGL <60 mg/dL', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (268, 'AEMT', 'Neurological', '', E'What is NOT a component of SAFER?', E'["Stabilize", "Assess", "Facilitate", "Restrain"]', 3, E'SAFER stands for Stabilize Assess Facilitate Encourage Referral (Restrain is not part of the acronym)', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (269, 'AEMT', 'Environmental', '', E'What level of hypothermia is a patient in who has a temperature of 89 degrees?', E'["Mild", "Moderate", "Severe", "Profound"]', 1, E'89°F (approx 31.6°C) falls into the Moderate hypothermia range (82-90°F)', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (270, 'AEMT', 'Medications', 'Procedures', E'What is the action of oxymetazaline?', E'["Vasodilator", "Vasoconstrictor", "Bronchodilator", "Analgesic"]', 1, E'Oxymetazoline is a vasoconstrictor used for epistaxis', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (271, 'AEMT', 'Medications', '', E'What medication should you administer to treat a dystonic reaction?', E'["Albuterol", "Diphenhydramine", "Epinephrine", "Ondansetron"]', 1, E'Diphenhydramine is used to treat dystonic reactions', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (272, 'AEMT', 'Environmental', '', E'What is NOT a symptom of heat stroke?', E'["Altered Mental Status", "Hot dry skin", "Hypotension", "Profuse sweating (usually absent)"]', 3, E'In heat stroke sweating generally disappears (skin is hot/dry) though not always; however classic teaching differentiates it from exhaustion by lack of sweating and AMS', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (273, 'AEMT', 'OB/Neonatal', 'OB/Neonatal', E'What should you do in the instance of a prolapsed cord?', E'["Push cord back in", "Insert gloved fingers to relieve pressure", "Clamp and cut cord", "Place patient in Fowler''s position"]', 1, E'Insert gloved hand to lift presenting part off the cord; do not push cord back in', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (274, 'AEMT', 'Neurological', '', E'How is status epilepticus defined?', E'["Seizure > 2 minutes", "Seizure > 5 minutes or recurrent without recovery", "Seizure > 10 minutes", "Any seizure"]', 1, E'Status epilepticus is defined as a seizure lasting >5 minutes or recurrent seizures without return to baseline', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (275, 'AEMT', 'Fluid Boluses', '', E'How much fluid should be administered in the cardiogenic shock protocol?', E'["250 mL", "500 mL", "1000 mL", "20 mL/kg"]', 1, E'Cardiogenic shock fluid administration is cautious often 250-500 mL boluses checking lung sounds', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (276, 'AEMT', 'Cardiovascular', '', E'Which one is a form of distributive shock?', E'["Hypovolemic", "Cardiogenic", "Septic", "Obstructive"]', 2, E'Septic shock is a type of distributive shock', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (277, 'AEMT', 'Burns', '', E'What are signs of smoke inhalation?', E'["Singed nasal hairs/Hoarseness", "Clear breath sounds", "Normal SpO2", "Bradycardia"]', 0, E'Signs include singed nasal hairs facial burns hoarseness and soot in sputum', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (278, 'AEMT', 'Cardiovascular', '', E'What is the medication and dose that an AEMT can administer for a patient with a suspected STEMI?', E'["Morphine 2mg", "Nitroglycerin 0.4mg SL", "Fentanyl 50mcg", "Aspirin 81mg"]', 1, E'AEMTs can administer Nitroglycerin 0.4 mg SL (if patient''s own or ambulance supply depending on jurisdiction protocol says ''Ambulance provided nitroglycerin'')', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (279, 'AEMT', 'Fluid Boluses', 'Pediatric', E'How much fluid should you give if a pediatric patient has a BGL >250?', E'["10 mL/kg", "20 mL/kg", "40 mL/kg", "60 mL/kg"]', 1, E'For pediatric hyperglycemia (BGL >250) with signs of dehydration 10-20 mL/kg is typical', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (280, 'AEMT', 'Transport Criteria', 'Transport/Admin', E'A patient has been administered two doses of D10 for hypoglycemia and is now no longer AMS and vital signs are within normal do they qualify for the waiting room?', E'["Yes", "No", "", ""]', 1, E'Patients who received D10 typically require observation/admission and are not appropriate for the waiting room', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (281, 'AEMT', 'Trauma', '', E'What does NOT meet NEXUS criteria for cervical stabilization?', E'["Midline cervical tenderness", "Intoxication", "Focal neurologic deficit", "Distracting injury"]', 3, E'NEXUS criteria require stabilization if: Tenderness AMS Intoxication Deficit or Distracting injury. If NONE exist spine is cleared. Absence of midline tenderness allows clearance if others met', E'SNHD Protocols');
INSERT INTO question (id, level, category, subcategory, question, options, correct_answer, explanation, source) VALUES (282, 'AEMT', 'Other', 'Medications', E'What medication can an AEMT administer to treat hyperkalemia?', E'["Calcium Chloride", "Sodium Bicarbonate", "Albuterol", "Insulin"]', 2, E'AEMTs can typically administer Albuterol (nebulized) which helps shift potassium intracellularly', E'SNHD Protocols');
